    #[test]
    fn css_transform_property_applies_like_attribute() {
        // style="transform: …" must match the presentation attribute path.
        let attr = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="20" height="10" fill="#0f0" transform="translate(30 40)"/>
        </svg>"##;
        let css = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <style>rect { transform: translate(30px, 40px); }</style>
          <rect x="0" y="0" width="20" height="10" fill="#0f0"/>
        </svg>"##;
        let a = svg_to_shapes(attr, 1_000_000, 1_000_000, 2).unwrap();
        let b = svg_to_shapes(css, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(a.shapes.len(), 1);
        assert_eq!(b.shapes.len(), 1);
        let ax = crate::element::write_element(&a.shapes[0]).unwrap();
        let bx = crate::element::write_element(&b.shapes[0]).unwrap();
        // Same off/ext after identical translate.
        assert_eq!(
            String::from_utf8_lossy(&ax),
            String::from_utf8_lossy(&bx),
            "CSS transform should match presentation attribute"
        );
    }

    #[test]
    fn image_data_svg_xml_expands_to_native_shapes() {
        // Compact red square as data:image/svg+xml (percent-encoded).
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <image x="10" y="10" width="40" height="40"
            href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 10 10'%3E%3Crect width='10' height='10' fill='%23ff0000'/%3E%3C/svg%3E"/>
          <foreignObject x="60" y="10" width="30" height="30">
            <div xmlns="http://www.w3.org/1999/xhtml">skip</div>
          </foreignObject>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(
            !conv.shapes.is_empty(),
            "data:image/svg+xml image should expand to native shapes"
        );
        let xml = conv
            .shapes
            .iter()
            .map(|s| String::from_utf8_lossy(&crate::element::write_element(s).unwrap()).into_owned())
            .collect::<Vec<_>>()
            .join("\n")
            .to_ascii_lowercase();
        assert!(
            xml.contains("ff0000") || xml.contains("solidfill"),
            "expected red fill from nested SVG image: {xml}"
        );
        // foreignObject must not invent text bodies
        assert!(!xml.contains("txbody"));
    }

