    #[test]
    fn alpha_mask_uses_paint_alpha_not_luminance() {
        // White at 40% alpha: luminance path would be ~0.4; alpha path is 0.4.
        // Black at 80% alpha: luminance path ~0, alpha path 0.8 — distinguish them.
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <mask id="a" mask-type="alpha">
              <rect width="100" height="100" fill="rgba(0,0,0,0.8)"/>
            </mask>
            <mask id="l">
              <rect width="100" height="100" fill="rgba(0,0,0,0.8)"/>
            </mask>
          </defs>
          <rect id="alpha" x="0" y="0" width="40" height="40" fill="#FF0000" mask="url(#a)"/>
          <rect id="lum" x="50" y="0" width="40" height="40" fill="#FF0000" mask="url(#l)"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 2);
        let alpha_xml = String::from_utf8_lossy(
            &crate::element::write_element(&conv.shapes[0]).unwrap(),
        )
        .into_owned();
        let lum_xml = String::from_utf8_lossy(
            &crate::element::write_element(&conv.shapes[1]).unwrap(),
        )
        .into_owned();
        // Alpha mask keeps non-trivial opacity from paint alpha.
        assert!(alpha_xml.contains("alpha"), "{alpha_xml}");
        // Luminance of pure black is 0 → effectively fully transparent paint.
        // Shape may still emit with alpha=0 or be skipped; either way no opaque red.
        let lum_has_opaque_red = lum_xml.contains("FF0000") && !lum_xml.contains("alpha");
        assert!(!lum_has_opaque_red, "{lum_xml}");
    }

