    #[test]
    fn non_scaling_stroke_ignores_ctm_scale() {
        // Under 2x scale, normal stroke doubles; non-scaling-stroke stays at 1px user width.
        let svg_scaled = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <g transform="scale(2)">
            <line x1="0" y1="10" x2="40" y2="10" stroke="#f00" stroke-width="2"/>
          </g>
        </svg>"##;
        let svg_noscale = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <g transform="scale(2)">
            <line x1="0" y1="10" x2="40" y2="10" stroke="#f00" stroke-width="2"
                  vector-effect="non-scaling-stroke"/>
          </g>
        </svg>"##;
        let scaled = svg_to_shapes(svg_scaled, 1_000_000, 1_000_000, 2).unwrap();
        let noscale = svg_to_shapes(svg_noscale, 1_000_000, 1_000_000, 2).unwrap();
        fn stroke_w(shapes: &[crate::element::OpenXmlElement]) -> i64 {
            for s in shapes {
                for d in s.descendants() {
                    if d.local_name == "ln" {
                        if let Some(w) = d.get_attribute("w") {
                            if let Ok(n) = w.parse::<i64>() {
                                if n > 0 {
                                    return n;
                                }
                            }
                        }
                    }
                }
            }
            0
        }
        let w_scaled = stroke_w(&scaled.shapes);
        let w_noscale = stroke_w(&noscale.shapes);
        assert!(w_scaled > 0 && w_noscale > 0, "missing stroke widths {w_scaled}/{w_noscale}");
        // non-scaling should be roughly half the scaled stroke (2x CTM).
        assert!(
            w_noscale * 2 < w_scaled + w_scaled / 4,
            "non-scaling stroke should ignore CTM scale: scaled={w_scaled} noscale={w_noscale}"
        );
        assert!(
            (w_scaled as f64 / w_noscale as f64 - 2.0).abs() < 0.35,
            "expected ~2x ratio, got scaled={w_scaled} noscale={w_noscale}"
        );
    }

    #[test]
    fn vector_effect_does_not_inherit() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <g vector-effect="non-scaling-stroke" transform="scale(3)">
            <line x1="0" y1="10" x2="30" y2="10" stroke="#0f0" stroke-width="1"/>
          </g>
        </svg>"##;
        // Child must NOT inherit non-scaling-stroke; stroke width should scale with CTM.
        let with_inherit_attempt = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        let plain = svg_to_shapes(
            br##"<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <g transform="scale(3)">
            <line x1="0" y1="10" x2="30" y2="10" stroke="#0f0" stroke-width="1"/>
          </g>
        </svg>"##,
            1_000_000,
            1_000_000,
            2,
        )
        .unwrap();
        fn stroke_w(shapes: &[crate::element::OpenXmlElement]) -> i64 {
            for s in shapes {
                for d in s.descendants() {
                    if d.local_name == "ln" {
                        if let Some(w) = d.get_attribute("w") {
                            if let Ok(n) = w.parse::<i64>() {
                                if n > 0 {
                                    return n;
                                }
                            }
                        }
                    }
                }
            }
            0
        }
        let a = stroke_w(&with_inherit_attempt.shapes);
        let b = stroke_w(&plain.shapes);
        assert_eq!(a, b, "vector-effect must not inherit: {a} vs {b}");
    }

    #[test]
    fn css_adjacent_and_general_sibling_combinators() {
        let root = parse_dom(
            r#"<svg>
              <style>
                rect + circle { fill: #ff0000; }
                .a ~ .b { stroke: #00ff00; stroke-width: 3; }
              </style>
              <rect class="a" width="10" height="10"/>
              <circle class="b" r="5"/>
              <ellipse class="b" rx="4" ry="3"/>
            </svg>"#,
        )
        .unwrap();
        let css = collect_css_rules(&root);
        let rect = &root.children[1];
        let circle = &root.children[2];
        let ellipse = &root.children[3];
        let prec_circle = vec![rect];
        let prec_ellipse = vec![rect, circle];
        let circle_style = Style::default().apply_node(circle, &css, &[], &prec_circle, Some((1, 3)), Some((0, 1)));
        let ellipse_style = Style::default().apply_node(ellipse, &css, &[], &prec_ellipse, Some((2, 3)), Some((0, 1)));
        let rect_style = Style::default().apply_node(rect, &css, &[], &[], Some((0, 3)), Some((0, 1)));
        assert_eq!(circle_style.fill.as_deref(), Some("#ff0000"));
        assert_eq!(ellipse_style.fill.as_deref(), Some("black")); // + only adjacent
        assert_eq!(ellipse_style.stroke.as_deref(), Some("#00ff00"));
        assert!((ellipse_style.stroke_width - 3.0).abs() < 1e-9);
        assert_eq!(rect_style.fill.as_deref(), Some("black"));
    }

