    #[test]
    fn word_spacing_widens_text_run() {
        let normal = br##"
        <svg viewBox="0 0 400 60" xmlns="http://www.w3.org/2000/svg">
          <text x="0" y="40" font-size="20" font-family="Liberation Sans, sans-serif"
                fill="#000">A B</text>
        </svg>"##;
        let spaced = br##"
        <svg viewBox="0 0 400 60" xmlns="http://www.w3.org/2000/svg">
          <text x="0" y="40" font-size="20" font-family="Liberation Sans, sans-serif"
                word-spacing="20" fill="#000">A B</text>
        </svg>"##;
        let n = svg_to_shapes(normal, 4_000_000, 600_000, 2).unwrap();
        let s = svg_to_shapes(spaced, 4_000_000, 600_000, 2).unwrap();
        fn max_x(shapes: &[crate::element::OpenXmlElement]) -> i64 {
            shapes.iter().filter_map(|sh| {
                let x = sh.descendants().find(|e| e.local_name=="off")?.get_attribute("x")?.parse::<i64>().ok()?;
                let cx = sh.descendants().find(|e| e.local_name=="ext")?.get_attribute("cx")?.parse::<i64>().ok()?;
                Some(x+cx)
            }).max().unwrap_or(0)
        }
        assert!(max_x(&s.shapes) > max_x(&n.shapes), "word-spacing should widen");
    }

