    #[test]
    fn dominant_baseline_middle_shifts_glyphs() {
        let alphabetic = br##"
        <svg viewBox="0 0 200 100" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="50" font-size="40" font-family="Liberation Sans, sans-serif"
                fill="#000">Ag</text>
        </svg>"##;
        let middle = br##"
        <svg viewBox="0 0 200 100" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="50" font-size="40" font-family="Liberation Sans, sans-serif"
                dominant-baseline="middle" fill="#000">Ag</text>
        </svg>"##;
        let a = svg_to_shapes(alphabetic, 2_000_000, 1_000_000, 2).unwrap();
        let m = svg_to_shapes(middle, 2_000_000, 1_000_000, 2).unwrap();
        assert!(!a.shapes.is_empty() && !m.shapes.is_empty());
        let ay: i64 = a.shapes.iter().map(|s| {
            s.descendants().find(|e| e.local_name == "off")
                .and_then(|e| e.get_attribute("y")).and_then(|v| v.parse().ok()).unwrap_or(0)
        }).min().unwrap();
        let my: i64 = m.shapes.iter().map(|s| {
            s.descendants().find(|e| e.local_name == "off")
                .and_then(|e| e.get_attribute("y")).and_then(|v| v.parse().ok()).unwrap_or(0)
        }).min().unwrap();
        // middle baseline moves glyphs upward relative to alphabetic at same y.
        assert!(my < ay, "middle baseline should shift glyphs up: mid={my} alpha={ay}");
    }

    #[test]
    fn text_length_spacing_stretches_run() {
        let normal = br##"
        <svg viewBox="0 0 400 80" xmlns="http://www.w3.org/2000/svg">
          <text x="0" y="40" font-size="20" font-family="Liberation Sans, sans-serif"
                fill="#000">ABCD</text>
        </svg>"##;
        let stretched = br##"
        <svg viewBox="0 0 400 80" xmlns="http://www.w3.org/2000/svg">
          <text x="0" y="40" font-size="20" font-family="Liberation Sans, sans-serif"
                textLength="200" lengthAdjust="spacing" fill="#000">ABCD</text>
        </svg>"##;
        let n = svg_to_shapes(normal, 4_000_000, 800_000, 2).unwrap();
        let s = svg_to_shapes(stretched, 4_000_000, 800_000, 2).unwrap();
        fn span_x(shapes: &[crate::element::OpenXmlElement]) -> (i64, i64) {
            let mut xs = Vec::new();
            for sh in shapes {
                for d in sh.descendants() {
                    if d.local_name == "off" {
                        if let Some(x) = d.get_attribute("x").and_then(|v| v.parse().ok()) {
                            xs.push(x);
                        }
                    }
                    if d.local_name == "ext" {
                        if let (Some(xoff), Some(cx)) = (
                            sh.descendants().find(|e| e.local_name == "off").and_then(|e| e.get_attribute("x")).and_then(|v| v.parse::<i64>().ok()),
                            d.get_attribute("cx").and_then(|v| v.parse::<i64>().ok()),
                        ) {
                            xs.push(xoff + cx);
                        }
                    }
                }
            }
            (*xs.iter().min().unwrap_or(&0), *xs.iter().max().unwrap_or(&0))
        }
        let (n0, n1) = span_x(&n.shapes);
        let (s0, s1) = span_x(&s.shapes);
        let nw = n1 - n0;
        let sw = s1 - s0;
        assert!(sw > nw, "textLength should widen run: normal={nw} stretched={sw}");
    }

    #[test]
    fn direction_rtl_mirrors_text_anchor() {
        let ltr = br##"
        <svg viewBox="0 0 400 80" xmlns="http://www.w3.org/2000/svg">
          <text x="200" y="40" font-size="20" font-family="Liberation Sans, sans-serif"
                text-anchor="start" fill="#000">Hi</text>
        </svg>"##;
        let rtl = br##"
        <svg viewBox="0 0 400 80" xmlns="http://www.w3.org/2000/svg">
          <text x="200" y="40" font-size="20" font-family="Liberation Sans, sans-serif"
                text-anchor="start" direction="rtl" unicode-bidi="bidi-override"
                fill="#000">Hi</text>
        </svg>"##;
        let a = svg_to_shapes(ltr, 4_000_000, 800_000, 2).unwrap();
        let b = svg_to_shapes(rtl, 4_000_000, 800_000, 2).unwrap();
        assert!(!a.shapes.is_empty() && !b.shapes.is_empty());
        fn min_x(shapes: &[crate::element::OpenXmlElement]) -> i64 {
            shapes.iter().filter_map(|s| {
                s.descendants().find(|e| e.local_name == "off")
                    .and_then(|e| e.get_attribute("x")).and_then(|v| v.parse().ok())
            }).min().unwrap_or(0)
        }
        let ax = min_x(&a.shapes);
        let bx = min_x(&b.shapes);
        // RTL start places the run to the left of x=200 (end-anchored in LTR terms).
        assert!(bx < ax, "rtl start should sit left of ltr start: ltr={ax} rtl={bx}");
    }

