    #[test]
    fn nth_child_odd_even_and_an_plus_b() {
        let root = parse_dom(
            r#"<svg>
              <style>
                rect:nth-child(odd) { fill: #111111; }
                rect:nth-child(even) { fill: #222222; }
                circle:nth-of-type(2n+1) { fill: #abcdef; }
                ellipse:not(.skip) { fill: #fedcba; }
              </style>
              <g>
                <rect width="10" height="10"/>
                <rect width="10" height="10"/>
                <circle r="5"/>
                <circle r="5"/>
                <ellipse class="skip" rx="3" ry="2"/>
                <ellipse rx="3" ry="2"/>
              </g>
            </svg>"#,
        )
        .unwrap();
        let css = collect_css_rules(&root);
        let g = &root.children[1];
        let r0 = &g.children[0];
        let r1 = &g.children[1];
        let c0 = &g.children[2];
        let c1 = &g.children[3];
        let e0 = &g.children[4];
        let e1 = &g.children[5];
        let s0 = Style::default().apply_node(r0, &css, &[g], &[], Some((0, 6)), Some((0, 2)));
        let s1 = Style::default().apply_node(r1, &css, &[g], &[r0], Some((1, 6)), Some((1, 2)));
        let sc0 = Style::default().apply_node(c0, &css, &[g], &[r0, r1], Some((2, 6)), Some((0, 2)));
        let sc1 = Style::default().apply_node(
            c1,
            &css,
            &[g],
            &[r0, r1, c0],
            Some((3, 6)),
            Some((1, 2)),
        );
        let se0 = Style::default().apply_node(
            e0,
            &css,
            &[g],
            &[r0, r1, c0, c1],
            Some((4, 6)),
            Some((0, 2)),
        );
        let se1 = Style::default().apply_node(
            e1,
            &css,
            &[g],
            &[r0, r1, c0, c1, e0],
            Some((5, 6)),
            Some((1, 2)),
        );
        assert_eq!(s0.fill.as_deref(), Some("#111111"), "r0 {:?}", s0.fill);
        assert_eq!(s1.fill.as_deref(), Some("#222222"), "r1 {:?}", s1.fill);
        assert_eq!(sc0.fill.as_deref(), Some("#abcdef"), "c0 {:?}", sc0.fill);
        assert_ne!(sc1.fill.as_deref(), Some("#abcdef"), "c1 {:?}", sc1.fill);
        assert_ne!(se0.fill.as_deref(), Some("#fedcba"), "e0 skip {:?}", se0.fill);
        assert_eq!(se1.fill.as_deref(), Some("#fedcba"), "e1 {:?}", se1.fill);
    }

    #[test]
    fn parse_nth_formula_variants() {
        assert_eq!(parse_nth_formula("odd"), Some((2, 1)));
        assert_eq!(parse_nth_formula("even"), Some((2, 0)));
        assert_eq!(parse_nth_formula("3"), Some((0, 3)));
        assert_eq!(parse_nth_formula("2n+1"), Some((2, 1)));
        assert_eq!(parse_nth_formula("-n+3"), Some((-1, 3)));
        assert_eq!(parse_nth_formula("n"), Some((1, 0)));
        assert!(nth_matches(1, 2, 1));
        assert!(!nth_matches(2, 2, 1));
        assert!(nth_matches(3, 2, 1));
        assert!(nth_matches(2, 2, 0));
    }

