    #[test]
    fn relative_color_from_fill_e2e() {
        let svg = br##"
        <svg viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
          <rect width="10" height="10" fill="color(from #336699 srgb r g b)"/>
          <rect y="12" width="10" height="10" fill="oklch(from red l c h)"/>
          <rect y="24" width="10" height="10" fill="hwb(from red h w b)"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(conv.shapes.len() >= 3);
        let a = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[0]).unwrap())
            .to_ascii_uppercase();
        let b = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[1]).unwrap())
            .to_ascii_uppercase();
        let c = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[2]).unwrap())
            .to_ascii_uppercase();
        assert!(a.contains("336699"), "color(from srgb) identity, got {a}");
        assert!(b.contains("FF0000") || (b.contains("FF") && !b.contains("00FF00")), "oklch from red, got {b}");
        assert!(c.contains("FF0000"), "hwb from red, got {c}");
    }

