    #[test]
    fn text_per_char_x_list_places_glyphs() {
        let sequential = br##"
        <svg viewBox="0 0 400 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="40" font-size="20" font-family="Liberation Sans, sans-serif"
                fill="#000">AB</text>
        </svg>"##;
        let listed = br##"
        <svg viewBox="0 0 400 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10 100" y="40" font-size="20" font-family="Liberation Sans, sans-serif"
                fill="#000">AB</text>
        </svg>"##;
        let a = svg_to_shapes(sequential, 4_000_000, 800_000, 2).unwrap();
        let b = svg_to_shapes(listed, 4_000_000, 800_000, 2).unwrap();
        assert!(!a.shapes.is_empty() && !b.shapes.is_empty());
        fn span_x(shapes: &[crate::element::OpenXmlElement]) -> (i64, i64) {
            let mut xs = Vec::new();
            for sh in shapes {
                for d in sh.descendants() {
                    if d.local_name == "off" {
                        if let Some(x) = d.get_attribute("x").and_then(|v| v.parse().ok()) {
                            xs.push(x);
                        }
                    }
                }
            }
            (
                *xs.iter().min().unwrap_or(&0),
                *xs.iter().max().unwrap_or(&0),
            )
        }
        let (a0, a1) = span_x(&a.shapes);
        let (b0, b1) = span_x(&b.shapes);
        let aw = a1 - a0;
        let bw = b1 - b0;
        assert!(bw > aw, "per-char x list should spread glyphs: seq={aw} list={bw}");
        assert!((b0 - a0).abs() < 50_000, "first glyph should stay near x=10");
    }

    #[test]
    fn text_rotate_list_emits_rotated_glyphs() {
        let plain = br##"
        <svg viewBox="0 0 200 100" xmlns="http://www.w3.org/2000/svg">
          <text x="20" y="50" font-size="30" font-family="Liberation Sans, sans-serif"
                fill="#000">A</text>
        </svg>"##;
        let rotated = br##"
        <svg viewBox="0 0 200 100" xmlns="http://www.w3.org/2000/svg">
          <text x="20" y="50" rotate="45" font-size="30" font-family="Liberation Sans, sans-serif"
                fill="#000">A</text>
        </svg>"##;
        let a = svg_to_shapes(plain, 2_000_000, 1_000_000, 2).unwrap();
        let b = svg_to_shapes(rotated, 2_000_000, 1_000_000, 2).unwrap();
        assert!(!a.shapes.is_empty() && !b.shapes.is_empty());
        // Rotated glyph bbox should differ from upright.
        fn bbox(shapes: &[crate::element::OpenXmlElement]) -> (i64, i64, i64, i64) {
            let mut min_x = i64::MAX;
            let mut min_y = i64::MAX;
            let mut max_x = i64::MIN;
            let mut max_y = i64::MIN;
            for sh in shapes {
                let mut ox = 0i64;
                let mut oy = 0i64;
                let mut cx = 0i64;
                let mut cy = 0i64;
                for d in sh.descendants() {
                    if d.local_name == "off" {
                        ox = d.get_attribute("x").and_then(|v| v.parse().ok()).unwrap_or(0);
                        oy = d.get_attribute("y").and_then(|v| v.parse().ok()).unwrap_or(0);
                    }
                    if d.local_name == "ext" {
                        cx = d.get_attribute("cx").and_then(|v| v.parse().ok()).unwrap_or(0);
                        cy = d.get_attribute("cy").and_then(|v| v.parse().ok()).unwrap_or(0);
                    }
                }
                min_x = min_x.min(ox);
                min_y = min_y.min(oy);
                max_x = max_x.max(ox + cx);
                max_y = max_y.max(oy + cy);
            }
            (min_x, min_y, max_x, max_y)
        }
        let ba = bbox(&a.shapes);
        let bb = bbox(&b.shapes);
        assert_ne!(ba, bb, "rotate should change glyph bbox: plain={ba:?} rot={bb:?}");
    }

