    #[test]
    fn writing_mode_vertical_stacks_glyphs() {
        let h = br##"
        <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
          <text x="100" y="20" font-size="24" font-family="Liberation Sans, sans-serif"
                fill="#000">AB</text>
        </svg>"##;
        let v = br##"
        <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
          <text x="100" y="20" font-size="24" font-family="Liberation Sans, sans-serif"
                writing-mode="vertical-rl" fill="#000">AB</text>
        </svg>"##;
        let a = svg_to_shapes(h, 2_000_000, 2_000_000, 2).unwrap();
        let b = svg_to_shapes(v, 2_000_000, 2_000_000, 2).unwrap();
        assert!(!a.shapes.is_empty() && !b.shapes.is_empty());
        fn span_y(shapes: &[crate::element::OpenXmlElement]) -> i64 {
            let mut ys = Vec::new();
            for sh in shapes {
                for d in sh.descendants() {
                    if d.local_name == "off" {
                        if let Some(y) = d.get_attribute("y").and_then(|v| v.parse().ok()) {
                            ys.push(y);
                        }
                    }
                    if d.local_name == "ext" {
                        if let (Some(yoff), Some(cy)) = (
                            sh.descendants()
                                .find(|e| e.local_name == "off")
                                .and_then(|e| e.get_attribute("y"))
                                .and_then(|v| v.parse::<i64>().ok()),
                            d.get_attribute("cy").and_then(|v| v.parse::<i64>().ok()),
                        ) {
                            ys.push(yoff + cy);
                        }
                    }
                }
            }
            ys.iter().max().copied().unwrap_or(0) - ys.iter().min().copied().unwrap_or(0)
        }
        let hy = span_y(&a.shapes);
        let vy = span_y(&b.shapes);
        assert!(vy > hy, "vertical writing-mode should increase Y span: h={hy} v={vy}");
    }

