    #[test]
    fn flood_color_inherits_from_filter_parent() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <filter id="f" x="-20%" y="-20%" width="140%" height="140%"
              flood-color="#00ff00" flood-opacity="0.8">
              <feDropShadow dx="2" dy="2" stdDeviation="1"/>
            </filter>
          </defs>
          <rect width="40" height="40" fill="#ffffff" filter="url(#f)"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        let all: String = conv
            .shapes
            .iter()
            .map(|s| {
                String::from_utf8_lossy(&crate::element::write_element(s).unwrap()).to_ascii_uppercase()
            })
            .collect();
        assert!(
            all.contains("00FF00") || all.contains("OUTERSHDW") || all.contains("EFFECTLST"),
            "filter-parent flood-color should influence shadow, got {all}"
        );
    }

