    #[test]
    fn overflow_position_grid_densify_cascade() {
        let mut m = std::collections::HashMap::new();
        m.insert("overflow".into(), "hidden auto".into());
        m.insert("position".into(), "absolute".into());
        m.insert("top".into(), "10px".into());
        m.insert("left".into(), "20%".into());
        m.insert("grid-row".into(), "1 / 3".into());
        m.insert("grid-column".into(), "2".into());
        m.insert("justify-items".into(), "center".into());
        m.insert("border-spacing".into(), "4px 8px".into());
        m.insert("counter-set".into(), "section 2".into());
        m.insert("content".into(), r#""x""#.into());
        let mut st = Style::default();
        apply_attr(&mut st, &m, None);
        assert_eq!(st.overflow, "hidden auto");
        assert_eq!(st.overflow_x, "hidden");
        assert_eq!(st.overflow_y, "auto");
        assert_eq!(st.css_position, "absolute");
        assert_eq!(st.css_top, "10px");
        assert_eq!(st.css_left, "20%");
        assert_eq!(st.grid_row, "1 / 3");
        assert_eq!(st.grid_column, "2");
        assert_eq!(st.justify_items, "center");
        assert_eq!(st.border_spacing, "4px 8px");
        assert_eq!(st.counter_set, "section 2");
        assert_eq!(st.css_content, r#""x""#);
        // longhands override shorthand axes
        let mut m2 = std::collections::HashMap::new();
        m2.insert("overflow".into(), "scroll".into());
        m2.insert("overflow-x".into(), "visible".into());
        let mut st2 = Style::default();
        apply_attr(&mut st2, &m2, None);
        assert_eq!(st2.overflow, "scroll");
        assert_eq!(st2.overflow_x, "visible");
        assert_eq!(st2.overflow_y, "scroll");
    }

