    #[test]
    fn animation_transition_container_densify() {
        let mut m = std::collections::HashMap::new();
        m.insert(
            "animation".into(),
            "fade 200ms ease-in 50ms 3 alternate forwards paused".into(),
        );
        m.insert("transition".into(), "opacity 100ms linear 10ms".into());
        m.insert("container".into(), "sidebar / inline-size".into());
        let mut st = Style::default();
        apply_attr(&mut st, &m, None);
        assert_eq!(st.animation_name, "fade");
        assert_eq!(st.animation_duration, "200ms");
        assert_eq!(st.animation_timing_function, "ease-in");
        assert_eq!(st.animation_delay, "50ms");
        assert_eq!(st.animation_iteration_count, "3");
        assert_eq!(st.animation_direction, "alternate");
        assert_eq!(st.animation_fill_mode, "forwards");
        assert_eq!(st.animation_play_state, "paused");
        assert_eq!(st.transition_property, "opacity");
        assert_eq!(st.transition_duration, "100ms");
        assert_eq!(st.transition_timing_function, "linear");
        assert_eq!(st.transition_delay, "10ms");
        assert_eq!(st.container_name, "sidebar");
        assert_eq!(st.container_type, "inline-size");
        // longhands after shorthand win when applied later in same map order depends on apply_attr sequence;
        // explicit longhand alone:
        let mut m2 = std::collections::HashMap::new();
        m2.insert("animation-delay".into(), "1s".into());
        m2.insert("transition-behavior".into(), "allow-discrete".into());
        let mut st2 = Style::default();
        apply_attr(&mut st2, &m2, None);
        assert_eq!(st2.animation_delay, "1s");
        assert_eq!(st2.transition_behavior, "allow-discrete");
    }

