    #[test]
    fn vector_effect_non_scaling_size_freezes_stroke() {
        let scaled = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <g transform="scale(2)">
            <line x1="0" y1="10" x2="40" y2="10" stroke="#0f0" stroke-width="2"
                  vector-effect="non-scaling-size"/>
          </g>
        </svg>"##;
        let plain = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <line x1="0" y1="10" x2="40" y2="10" stroke="#0f0" stroke-width="2"
                vector-effect="non-scaling-size"/>
        </svg>"##;
        let a = svg_to_shapes(scaled, 1_000_000, 1_000_000, 2).unwrap();
        let b = svg_to_shapes(plain, 1_000_000, 1_000_000, 2).unwrap();
        fn stroke_w(shapes: &[crate::element::OpenXmlElement]) -> i64 {
            for s in shapes {
                for d in s.descendants() {
                    if d.local_name == "ln" {
                        if let Some(w) = d.get_attribute("w") {
                            if let Ok(n) = w.parse::<i64>() {
                                if n > 0 {
                                    return n;
                                }
                            }
                        }
                    }
                }
            }
            0
        }
        let wa = stroke_w(&a.shapes);
        let wb = stroke_w(&b.shapes);
        assert!(wa > 0 && wb > 0, "wa={wa} wb={wb}");
        // non-scaling-size: scaled CTM should not double stroke vs unscaled.
        assert!(
            (wa as f64 / wb as f64 - 1.0).abs() < 0.35,
            "expected similar stroke, got scaled={wa} plain={wb}"
        );
    }

    
    #[test]
    fn vector_effect_non_scaling_size_strips_ctm_scale() {
        let m = Matrix { a: 2.0, b: 0.0, c: 0.0, d: 2.0, e: 10.0, f: 20.0 };
        let mut st = Style::default();
        st.vector_effect = "non-scaling-size".into();
        let out = ctm_for_vector_effect(&st, m);
        assert!((out.a - 1.0).abs() < 1e-9, "a={}", out.a);
        assert!((out.d - 1.0).abs() < 1e-9, "d={}", out.d);
        assert!((out.e - 10.0).abs() < 1e-9);
        assert!((out.f - 20.0).abs() < 1e-9);
        // rotation preserved under scale strip
        let ang = std::f64::consts::FRAC_PI_4;
        let rot = Matrix {
            a: 2.0 * ang.cos(),
            b: 2.0 * ang.sin(),
            c: -2.0 * ang.sin(),
            d: 2.0 * ang.cos(),
            e: 0.0,
            f: 0.0,
        };
        let out2 = ctm_for_vector_effect(&st, rot);
        let sx = (out2.a * out2.a + out2.b * out2.b).sqrt();
        assert!((sx - 1.0).abs() < 1e-6, "unit scale after strip, sx={sx}");
    }

