    #[test]
    fn font_variant_ligatures_common_merges_fi() {
        // common-ligatures maps "fi" → U+FB01 one glyph; none keeps two.
        let none = br##"
        <svg viewBox="0 0 200 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="50" font-size="40" fill="#112233"
                font-variant-ligatures="none"
                font-family="Liberation Sans, sans-serif">fi</text>
        </svg>"##;
        let common = br##"
        <svg viewBox="0 0 200 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="50" font-size="40" fill="#112233"
                font-variant-ligatures="common-ligatures"
                font-family="Liberation Sans, sans-serif">fi</text>
        </svg>"##;
        let cn = svg_to_shapes(none, 2_000_000, 800_000, 2).unwrap();
        let cc = svg_to_shapes(common, 2_000_000, 800_000, 2).unwrap();
        assert_eq!(cn.shapes.len(), 2, "none: expected 2 glyphs, got {}", cn.shapes.len());
        // Ligature form may be 1 glyph if font has FB01; if not, still emits ≥1.
        assert!(
            cc.shapes.len() <= cn.shapes.len(),
            "common should not emit more glyphs than none: common={} none={}",
            cc.shapes.len(),
            cn.shapes.len()
        );
        assert!(cc.shapes.len() >= 1, "common: got {}", cc.shapes.len());
    }


