    #[test]
    fn stroke_alignment_inner_outer_cascade() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <rect x="10" y="10" width="40" height="40" fill="none"
                stroke="#ff0000" stroke-width="4" stroke-alignment="inner"/>
          <rect x="50" y="10" width="40" height="40" fill="none"
                stroke="#00ff00" stroke-width="4" stroke-alignment="outer"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 2);
        fn stroke_w(s: &crate::element::OpenXmlElement) -> i64 {
            for d in s.descendants() {
                if d.local_name == "ln" {
                    if let Some(w) = d.get_attribute("w") {
                        if let Ok(n) = w.parse::<i64>() {
                            if n > 0 {
                                return n;
                            }
                        }
                    }
                }
            }
            0
        }
        let w0 = stroke_w(&conv.shapes[0]);
        let w1 = stroke_w(&conv.shapes[1]);
        assert!(w0 > 0 && w1 > 0, "w0={w0} w1={w1}");
        // Geometry offset keeps nominal stroke width equal; outer expands cx/cy.
        assert!(
            (w0 - w1).abs() < w0 / 10 + 1,
            "stroke widths should match after geometry offset: inner={w0} outer={w1}"
        );
        fn ext_cx(s: &crate::element::OpenXmlElement) -> i64 {
            for d in s.descendants() {
                if d.local_name == "ext" {
                    if let Some(cx) = d.get_attribute("cx") {
                        if let Ok(n) = cx.parse::<i64>() {
                            return n;
                        }
                    }
                }
            }
            0
        }
        let cx0 = ext_cx(&conv.shapes[0]);
        let cx1 = ext_cx(&conv.shapes[1]);
        assert!(
            cx1 > cx0,
            "outer geometry should be larger than inner: inner_cx={cx0} outer_cx={cx1}"
        );
    }

    #[test]
    fn text_shadow_cascade_and_outer_shdw() {
        let svg = br##"
        <svg viewBox="0 0 200 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="40" font-size="24" fill="#112233"
                text-shadow="3px 4px 2px rgba(0,0,0,0.5)">Hi</text>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        let mut found = false;
        for sh in &conv.shapes {
            for d in sh.descendants() {
                if d.local_name == "outerShdw" {
                    found = true;
                    break;
                }
            }
            if found {
                break;
            }
        }
        assert!(found, "text-shadow should produce outerShdw on glyph shapes");
        // Parser smoke
        let sh = parse_text_shadow("2px 3px 1px #112233").expect("parse");
        assert!((sh.dx - 2.0).abs() < 1e-6);
        assert!((sh.dy - 3.0).abs() < 1e-6);
        assert!((sh.blur - 1.0).abs() < 1e-6);
        assert_eq!(sh.rgb, [0x11, 0x22, 0x33]);
        assert!(parse_text_shadow("none").is_none());
    }

