    #[test]
    fn font_variation_and_text_overflow_cascade() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <g style="font-variation-settings: 'wght' 700; hanging-punctuation: first;
                    text-align-last: justify; font-language-override: 'ENG'">
            <text x="10" y="20" font-size="12" text-overflow="ellipsis"
                  fill="#000">ab</text>
          </g>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        // Walk internal style via a tiny re-apply: ensure convert succeeded and
        // presentation attrs didn't panic. Deeper cascade asserted via helpers
        // on synthetic Style.
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert(
                    "font-variation-settings".into(),
                    "'wght' 700".into(),
                );
                m.insert("hanging-punctuation".into(), "first".into());
                m.insert("text-align-last".into(), "justify".into());
                m.insert("font-language-override".into(), "ENG".into());
                m.insert("text-overflow".into(), "ellipsis".into());
                m
            },
            None,
        );
        assert!(st.font_variation_settings.contains("wght"));
        assert_eq!(st.hanging_punctuation, "first");
        assert_eq!(st.text_align_last, "justify");
        assert!(st.font_language_override.contains("ENG") || st.font_language_override.contains("eng") || st.font_language_override == "ENG");
        assert_eq!(st.text_overflow, "ellipsis");
        let _ = conv;
    }

    #[test]
    fn text_decoration_skip_ink_and_font_palette_cascade() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("text-decoration-skip-ink".into(), "none".into());
                m.insert("font-palette".into(), "dark".into());
                m.insert("color-scheme".into(), "only dark".into());
                m.insert("print-color-adjust".into(), "exact".into());
                m.insert("forced-color-adjust".into(), "none".into());
                m.insert("accent-color".into(), "#ff00aa".into());
                m.insert("quotes".into(), r#""«" "»" "‹" "›""#.into());
                m.insert("image-orientation".into(), "none".into());
                m.insert("object-fit".into(), "contain".into());
                m.insert("object-position".into(), "10% 20%".into());
                m
            },
            None,
        );
        assert_eq!(st.text_decoration_skip_ink, "none");
        assert_eq!(st.font_palette, "dark");
        assert!(st.color_scheme.contains("dark"));
        assert_eq!(st.print_color_adjust, "exact");
        assert_eq!(st.forced_color_adjust, "none");
        assert!(st.accent_color.contains("ff00aa") || st.accent_color.contains("#ff00aa"));
        assert!(st.quotes.contains('«') || st.quotes.contains("«"));
        assert_eq!(st.image_orientation, "none");
        assert_eq!(st.object_fit, "contain");
        assert!(st.object_position.contains("10%"));

        // Integration: underline still emits with skip-ink none
        let svg = br##"
        <svg viewBox="0 0 200 60" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="40" font-size="20" fill="#000"
                text-decoration="underline"
                text-decoration-skip-ink="none">gy</text>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(conv.shapes.len() >= 2, "glyphs + underline, got {}", conv.shapes.len());
    }

    
    #[test]
    fn font_palette_light_dark_adjusts_fill() {
        assert_eq!(apply_font_palette_to_fill(Some("#808080"), "normal"), None);
        let light = apply_font_palette_to_fill(Some("#808080"), "light").unwrap();
        let dark = apply_font_palette_to_fill(Some("#808080"), "dark").unwrap();
        let lr = u8::from_str_radix(light.trim_start_matches('#').get(0..2).unwrap_or("00"), 16).unwrap();
        let dr = u8::from_str_radix(dark.trim_start_matches('#').get(0..2).unwrap_or("ff"), 16).unwrap();
        assert!(lr > 0x80, "light={light}");
        assert!(dr < 0x80, "dark={dark}");
        let svg = br##"<svg xmlns="http://www.w3.org/2000/svg" width="100" height="40">
            <text x="0" y="30" font-size="20" fill="#808080" font-palette="dark">A</text>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        let xml = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[0]).unwrap())
            .to_ascii_uppercase();
        assert!(
            !xml.contains("808080"),
            "expected darkened fill not #808080, got {xml}"
        );
    }

#[test]
    fn object_fit_and_image_orientation_do_not_inherit() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <g style="object-fit: cover; image-orientation: 90deg; object-position: 0 0">
            <rect x="0" y="0" width="10" height="10" fill="#f00"/>
          </g>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 1);
        // non-inherited: child rect defaults after apply_node reset
        let mut parent = Style::default();
        parent.object_fit = "cover".into();
        parent.image_orientation = "90deg".into();
        parent.object_position = "0 0".into();
        // Simulate apply_node reset for non-inherited
        let mut child = parent.clone();
        child.object_fit = "fill".into();
        child.image_orientation = "from-image".into();
        child.object_position = "50% 50%".into();
        assert_eq!(child.object_fit, "fill");
        assert_eq!(child.image_orientation, "from-image");
        let _ = conv;
    }

    #[test]
    fn vector_effect_non_rotation_drops_ctm_rotation() {
        // 90° rotate would swap axes; non-rotation keeps axis-aligned scales.
        let m = Matrix {
            a: 0.0,
            b: 1.0,
            c: -1.0,
            d: 0.0,
            e: 10.0,
            f: 20.0,
        };
        let mut st = Style::default();
        st.vector_effect = "non-rotation".into();
        let out = ctm_for_vector_effect(&st, m);
        assert!((out.b).abs() < 1e-9 && (out.c).abs() < 1e-9, "rotation cleared: {out:?}");
        assert!((out.a - 1.0).abs() < 1e-6, "sx: {}", out.a);
        assert!((out.d - 1.0).abs() < 1e-6, "sy: {}", out.d);
        assert!((out.e - 10.0).abs() < 1e-6);
        assert!((out.f - 20.0).abs() < 1e-6);

        st.vector_effect = "fixed-position".into();
        let id = ctm_for_vector_effect(&st, m);
        assert!((id.a - 1.0).abs() < 1e-9 && id.e.abs() < 1e-9 && id.f.abs() < 1e-9);

        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <g transform="rotate(45 50 50)">
            <rect x="40" y="40" width="20" height="10" fill="#0f0"
                  vector-effect="non-rotation"/>
          </g>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 1);
    }

    #[test]
    fn object_fit_contain_maps_to_meet_par() {
        let mut st = Style::default();
        st.object_fit = "contain".into();
        st.object_position = "left top".into();
        let (par, clip) = object_fit_preserve(&st, None);
        assert!(par.to_ascii_lowercase().contains("meet"), "{par}");
        assert!(par.contains("xMin") || par.contains("xmin"), "{par}");
        assert!(!clip);

        st.object_fit = "cover".into();
        st.object_position = "right bottom".into();
        let (par, clip) = object_fit_preserve(&st, None);
        assert!(par.to_ascii_lowercase().contains("slice"), "{par}");
        assert!(clip);

        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"
             xmlns:xlink="http://www.w3.org/1999/xlink">
          <image x="10" y="10" width="40" height="40" object-fit="cover"
            href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 10'%3E%3Crect width='20' height='10' fill='%2300ff00'/%3E%3C/svg%3E"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty(), "cover image should expand nested svg");
        assert!(parse_image_orientation_deg("90deg").unwrap() - 90.0 < 1e-6);
        assert!(parse_image_orientation_deg("from-image").is_none());
    }

    #[test]
