    #[test]
    fn text_stroke_and_content_visibility_cascade() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("-webkit-text-stroke".into(), "1.5px #ff0000".into());
                m.insert("content-visibility".into(), "hidden".into());
                m.insert("backdrop-filter".into(), "blur(4px)".into());
                m.insert("text-justify".into(), "inter-word".into());
                m.insert("ruby-position".into(), "under".into());
                m.insert("user-select".into(), "none".into());
                m.insert("caret-color".into(), "red".into());
                m.insert("appearance".into(), "auto".into());
                m.insert("will-change".into(), "transform".into());
                m
            },
            None,
        );
        assert!((st.text_stroke_width - 1.5).abs() < 1e-6, "{}", st.text_stroke_width);
        assert_eq!(st.text_stroke_color.as_deref(), Some("#ff0000"));
        assert_eq!(st.content_visibility, "hidden");
        assert!(st.backdrop_filter.contains("blur"));
        assert_eq!(st.text_justify, "inter-word");
        assert_eq!(st.ruby_position, "under");
        assert_eq!(st.user_select, "none");
        assert_eq!(st.caret_color, "red");
        assert_eq!(st.appearance, "auto");
        assert!(st.will_change.contains("transform"));

        let svg = br##"
        <svg viewBox="0 0 100 40" xmlns="http://www.w3.org/2000/svg">
          <text x="5" y="25" font-size="18" fill="#00f"
                style="-webkit-text-stroke: 1px #000">A</text>
          <rect x="0" y="0" width="10" height="10" fill="#f00"
                style="content-visibility: hidden"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        // glyph fill + stroke; hidden rect omitted
        assert!(conv.shapes.len() >= 2, "text stroke + fill, got {}", conv.shapes.len());
        assert!(
            conv.shapes.len() < 5,
            "hidden rect should not paint, got {}",
            conv.shapes.len()
        );
    }

    #[test]
    fn offset_path_places_shape_along_path() {
        let mut st = Style::default();
        st.offset_path = Some(r#"path("M0 0 L100 0")"#.into());
        st.offset_distance = 0.5;
        st.offset_distance_is_pct = true;
        st.offset_rotate = "0deg".into();
        let ctm = ctm_with_offset_path(&st, Matrix::identity());
        // At 50% of horizontal path: translate ~50,0
        assert!((ctm.e - 50.0).abs() < 1e-3, "e={}", ctm.e);
        assert!(ctm.f.abs() < 1e-3, "f={}", ctm.f);

        let svg = br##"
        <svg viewBox="0 0 120 40" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="10" height="10" fill="#0f0"
                style="offset-path: path('M0 20 L100 20'); offset-distance: 100%; offset-rotate: 0deg"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 1);
    }

    #[test]
    fn offset_path_url_hash_uses_path_index() {
        let svg = br##"
        <svg viewBox="0 0 200 100" xmlns="http://www.w3.org/2000/svg">
          <path id="p" d="M0 50 L100 50" fill="none"/>
          <rect x="0" y="0" width="10" height="10" fill="#0f0"
                style="offset-path: url(#p); offset-distance: 50%; offset-rotate: 0deg"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        // viewBox 200 → 1e6; 1 user = 5000 EMU. mid path x=50 → ~250000
        let mut min_x = i64::MAX;
        for sh in &conv.shapes {
            for d in sh.descendants() {
                if d.local_name == "off" {
                    if let Some(x) = d.get_attribute("x") {
                        if let Ok(n) = x.parse::<i64>() {
                            min_x = min_x.min(n);
                        }
                    }
                }
            }
        }
        assert!(
            min_x > 200_000 && min_x < 300_000,
            "url(#p) 50% of M0 50 L100 50 should place near x=50, min_x={min_x}"
        );
    }

