                m.insert("column-fill".into(), "auto".into());
                m.insert("column-rule".into(), "1px solid red".into());
                m.insert("font-variant-alternates".into(), "historical-forms".into());
                m.insert("math-style".into(), "compact".into());
                m.insert("math-depth".into(), "1".into());
                m.insert("math-shift".into(), "compact".into());
                m.insert("text-edge".into(), "cap alphabetic".into());
                m.insert("leading-trim".into(), "both".into());
                m.insert("margin-trim".into(), "block".into());
                m.insert("baseline-source".into(), "first".into());
                m.insert("hyphenate-limit-chars".into(), "6 3 2".into());
                m.insert("text-autospace".into(), "ideograph-alpha".into());
