    #[test]
    fn initial_letter_scale_parses_and_enlarges_first_glyph() {
        assert_eq!(initial_letter_scale("normal"), None);
        assert_eq!(initial_letter_scale("3"), Some(3.0));
        assert_eq!(initial_letter_scale("3 2"), Some(3.0));
        let svg = br##"
        <svg viewBox="0 0 200 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="50" font-size="12" fill="#000"
                initial-letter="3">Hi</text>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(conv.shapes.len() >= 2, "expected at least H and i glyphs");
        // First glyph (H) should occupy larger bbox than second when scaled 3x.
        let mut boxes = Vec::new();
        for sh in &conv.shapes {
            let mut x: Option<i64> = None;
            let mut y: Option<i64> = None;
            let mut cx: Option<i64> = None;
            let mut cy: Option<i64> = None;
            for d in sh.descendants() {
                if d.local_name == "off" {
                    x = d.get_attribute("x").and_then(|v| v.parse().ok());
                    y = d.get_attribute("y").and_then(|v| v.parse().ok());
                }
                if d.local_name == "ext" {
                    cx = d.get_attribute("cx").and_then(|v| v.parse().ok());
                    cy = d.get_attribute("cy").and_then(|v| v.parse().ok());
                }
            }
            if let (Some(x), Some(y), Some(cx), Some(cy)) = (x, y, cx, cy) {
                boxes.push((x, y, cx, cy));
            }
        }
        assert!(boxes.len() >= 2);
        let h0 = boxes[0].3;
        let h1 = boxes[1].3;
        assert!(h0 as f64 > h1 as f64 * 1.5, "first glyph height {h0} should exceed second {h1}");
    }

