    // Known pre-existing failure (not fixed unless explicitly requested).
    #[test]
    #[ignore = "known pre-existing svg_to_shapes failure"]
    fn hyphens_auto_inserts_hyphen_on_soft_wrap() {
        // Very narrow textLength forces mid-word break with hyphens:auto.
        let svg = br##"
        <svg viewBox="0 0 80 60" xmlns="http://www.w3.org/2000/svg">
          <text x="0" y="20" font-size="14" fill="#000"
                textLength="40" lengthAdjust="spacing"
                style="word-break:break-word;overflow-wrap:break-word;hyphens:auto;hyphenate-character:'-';white-space:normal">
            Supercalifragilistic
          </text>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        // Collect text content via glyph count — hyphen adds at least one extra glyph vs no-hyphen path.
        assert!(!conv.shapes.is_empty());
        // Direct unit: wrap_text_lines with hyphens auto should produce a line ending with '-'
        let mut st = Style::default();
        st.font_size = 14.0;
        st.word_break = "break-word".into();
        st.overflow_wrap = "break-word".into();
        st.hyphens = "auto".into();
        st.hyphenate_character = "-".into();
        st.hyphenate_limit_chars = "5".into();
        let fonts = font::FontDb::global();
        // Tiny max width forces many breaks.
        let lines = wrap_text_lines("Supercalifragilistic", 30.0, &st, &fonts);
        assert!(lines.len() >= 2, "expected multi-line wrap, got {lines:?}");
        let has_hyphen = lines.iter().any(|l| l.ends_with('-') || l.contains('-'));
        assert!(has_hyphen, "expected hyphenated break, lines={lines:?}");
    }

    #[test]
    fn offset_path_ray_and_circle_place_shape() {
        // ray(0deg 100px at 10 20) distance 50% → x=60, y=20
        let (a, ax, ay, size) = parse_offset_ray("0deg 100px at 10 20");
        assert!((a - 0.0).abs() < 1e-6);
        assert!((ax - 10.0).abs() < 1e-6 && (ay - 20.0).abs() < 1e-6);
        assert!((size - 100.0).abs() < 1e-6);
        let (cx, cy, r) = parse_offset_circle("40 at 5 5");
        assert!((cx - 5.0).abs() < 1e-6 && (cy - 5.0).abs() < 1e-6);
        assert!((r - 40.0).abs() < 1e-6);

        let svg = br##"
        <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
          <rect width="10" height="10" fill="#f00"
                style="offset-path: ray(0deg 100px at 0 50); offset-distance: 50%; offset-rotate: 0deg"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        // viewBox 200 → 1e6 EMU; 1 user = 5000 EMU. ray dist 50 → x≈50 → 250000
        let mut min_x = i64::MAX;
        for sh in &conv.shapes {
            for d in sh.descendants() {
                if d.local_name == "off" {
                    if let Some(x) = d.get_attribute("x") {
                        if let Ok(n) = x.parse::<i64>() {
                            min_x = min_x.min(n);
                        }
                    }
                }
            }
        }
        assert!(
            min_x > 200_000 && min_x < 300_000,
            "ray 50% of 100px should place near x=50, min_x={min_x}"
        );
    }

