    #[test]
    fn object_fit_scale_down_uses_none_when_intrinsic_fits() {
        // Inner SVG 20x20 into 100x100 box → scale-down ≡ none (no upscale).
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <image x="0" y="0" width="100" height="100" object-fit="scale-down"
                 href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 20'%3E%3Crect width='20' height='20' fill='%2300f'/%3E%3C/svg%3E"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        // 20 user units in 100-viewBox → 20% of 1e6 = 200_000 EMU extent if unscaled.
        let mut max_cx = 0i64;
        for sh in &conv.shapes {
            for d in sh.descendants() {
                if d.local_name == "ext" {
                    if let Some(cx) = d.get_attribute("cx").and_then(|v| v.parse().ok()) {
                        max_cx = max_cx.max(cx);
                    }
                }
            }
        }
        // Unscaled 20/100 of slide → ~200k; contain would stretch to ~1e6.
        assert!(
            max_cx > 0 && max_cx < 400_000,
            "scale-down should not upscale small intrinsic, max_cx={max_cx}"
        );
    }

