    #[test]
    fn object_view_box_inset_and_line_height_step() {
        let base = (0.0, 0.0, 100.0, 100.0);
        let vb = parse_object_view_box("inset(10%)", base).unwrap();
        assert!((vb.0 - 10.0).abs() < 1e-6 && (vb.1 - 10.0).abs() < 1e-6);
        assert!((vb.2 - 80.0).abs() < 1e-6 && (vb.3 - 80.0).abs() < 1e-6);
        let vb2 = parse_object_view_box("xywh(10 20 30 40)", base).unwrap();
        assert!((vb2.0 - 10.0).abs() < 1e-6 && (vb2.1 - 20.0).abs() < 1e-6);
        assert!((vb2.2 - 30.0).abs() < 1e-6 && (vb2.3 - 40.0).abs() < 1e-6);

        let mut st = Style::default();
        st.font_size = 10.0;
        st.line_height = 1.2; // 12px
        st.line_height_step = "8".into(); // snap to 16
        let lh = effective_line_height_px(&st);
        assert!((lh - 16.0).abs() < 1e-6, "got {lh}");
    }

