    #[test]
    fn box_shadow_sets_css_filter_shadow() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("box-shadow".into(), "3px 4px 2px #000000".into());
                m
            },
            None,
        );
        let sh = st.css_filter_shadow.expect("box-shadow should parse to outerShdw");
        assert!((sh.dx - 3.0).abs() < 1e-6);
        assert!((sh.dy - 4.0).abs() < 1e-6);
        assert!((sh.blur - 2.0).abs() < 1e-6);

        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <rect x="20" y="20" width="40" height="40" fill="#f00"
                style="box-shadow: 2px 2px 1px #000"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        let mut has_shdw = false;
        for sh in &conv.shapes {
            for d in sh.descendants() {
                if d.local_name == "outerShdw" {
                    has_shdw = true;
                }
            }
        }
        assert!(has_shdw, "box-shadow should emit outerShdw on shape");
    }

    #[test]
    fn box_shadow_inset_emits_inner_shdw() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("box-shadow".into(), "inset 2px 3px 4px #112233".into());
                m
            },
            None,
        );
        let sh = st.css_filter_shadow.expect("inset box-shadow parses");
        assert!(sh.inset);
        assert!((sh.dx - 2.0).abs() < 1e-6);
        assert!((sh.dy - 3.0).abs() < 1e-6);
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <rect x="10" y="10" width="40" height="30" fill="#abc"
                style="box-shadow: inset 2px 2px 3px #000"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        let mut found = false;
        for sh in &conv.shapes {
            for d in sh.descendants() {
                if d.local_name == "innerShdw" {
                    found = true;
                    break;
                }
            }
            if found {
                break;
            }
        }
        assert!(found, "expected a:innerShdw for inset box-shadow");
    }


    #[test]
    fn multi_layer_box_shadow_emits_ghost_underlays() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert(
                    "box-shadow".into(),
                    "1px 2px 0 #ff0000, 3px 4px 1px #0000ff".into(),
                );
                m
            },
            None,
        );
        let primary = st.css_filter_shadow.expect("first shadow primary");
        assert!((primary.dx - 1.0).abs() < 1e-6);
        assert!((primary.dy - 2.0).abs() < 1e-6);
        assert_eq!(primary.rgb, [0xff, 0, 0]);
        assert_eq!(st.extra_shadows.len(), 1, "second layer as extra");
        assert!((st.extra_shadows[0].dx - 3.0).abs() < 1e-6);
        assert_eq!(st.extra_shadows[0].rgb, [0, 0, 0xff]);

        let svg_path = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <path d="M20 20 H50 V50 H20 Z" fill="#0f0"
                style="box-shadow: 1px 1px 0 #111, 4px 5px 0 #222"/>
        </svg>"##;
        let conv = svg_to_shapes(svg_path, 1_000_000, 1_000_000, 2).unwrap();
        assert!(
            conv.shapes.len() >= 2,
            "path multi box-shadow should emit ghost underlay, got {}",
            conv.shapes.len()
        );
        let svg_rect = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <rect x="20" y="20" width="30" height="30" fill="#0f0"
                style="box-shadow: 1px 1px 0 #111, 4px 5px 0 #222"/>
        </svg>"##;
        let conv = svg_to_shapes(svg_rect, 1_000_000, 1_000_000, 2).unwrap();
        assert!(
            conv.shapes.len() >= 2,
            "rect multi box-shadow should emit ghost underlay, got {}",
            conv.shapes.len()
        );
        let mut has_outer = false;
        let mut ghost = 0usize;
        for sh in &conv.shapes {
            if sh.get_attribute("name").map(|n| n.contains("shdwGhost")).unwrap_or(false)
                || format!("{:?}", sh).contains("shdwGhost")
            {
                ghost += 1;
            }
            for d in sh.descendants() {
                if d.local_name == "outerShdw" {
                    has_outer = true;
                }
                // Shape name lives on p:cNvPr
                if d.local_name == "cNvPr" {
                    if let Some(n) = d.get_attribute("name") {
                        if n.contains("shdwGhost") {
                            ghost += 1;
                        }
                    }
                }
            }
        }
        assert!(has_outer, "primary layer should still emit outerShdw");
        assert!(ghost >= 1, "expected shdwGhost underlay shape");
    }

    #[test]
    fn multi_layer_text_shadow_parses_extras() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert(
                    "text-shadow".into(),
                    "1px 1px 0 #000, 2px 3px 1px rgba(255,0,0,0.5)".into(),
                );
                m
            },
            None,
        );
        let sh = st.text_shadow.expect("first text-shadow");
        assert!((sh.dx - 1.0).abs() < 1e-6);
        assert_eq!(st.extra_text_shadows.len(), 1);
        assert!((st.extra_text_shadows[0].dx - 2.0).abs() < 1e-6);
        assert!((st.extra_text_shadows[0].dy - 3.0).abs() < 1e-6);
        assert_eq!(
            st.extra_text_shadows[0].rgb,
            [255, 0, 0],
            "extra text shadow color {:?}",
            st.extra_text_shadows[0]
        );

        let list = parse_shadow_list("none");
        assert!(list.is_empty());
        let list = parse_shadow_list("1px 2px #abc, inset 3px 4px 2px #def");
        assert_eq!(list.len(), 2);
        assert!(!list[0].inset);
        assert!(list[1].inset);
    }


    #[test]
    fn multi_drop_shadow_filter_extras() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert(
                    "filter".into(),
                    "drop-shadow(1px 2px 0 #112233) drop-shadow(3px 4px 1px #445566)".into(),
                );
                m
            },
            None,
        );
        let sh = st.css_filter_shadow.expect("first drop-shadow");
        assert!((sh.dx - 1.0).abs() < 1e-6);
        assert_eq!(sh.rgb, [0x11, 0x22, 0x33]);
        assert_eq!(st.extra_shadows.len(), 1);
        assert!((st.extra_shadows[0].dx - 3.0).abs() < 1e-6);
        assert_eq!(st.extra_shadows[0].rgb, [0x44, 0x55, 0x66]);

        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <path d="M10 10 H40 V40 H10 Z" fill="#0f0"
                style="filter: drop-shadow(1px 1px 0 #000) drop-shadow(4px 5px 0 #222)"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(
            conv.shapes.len() >= 2,
            "multi drop-shadow filter should ghost underlay, got {}",
            conv.shapes.len()
        );
        let mut ghost = 0usize;
        for sh in &conv.shapes {
            for d in sh.descendants() {
                if d.local_name == "cNvPr" {
                    if let Some(n) = d.get_attribute("name") {
                        if n.contains("shdwGhost") {
                            ghost += 1;
                        }
                    }
                }
            }
        }
        assert!(ghost >= 1, "expected shdwGhost from second drop-shadow()");
    }


    #[test]
    fn font_weight_bolder_lighter_relative() {
        let mut parent = Style::default();
        parent.font_weight = "300".into();
        let mut child = Style::default();
        apply_attr(
            &mut child,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("font-weight".into(), "bolder".into());
                m
            },
            Some(&parent),
        );
        assert_eq!(child.font_weight, "400");
        parent.font_weight = "500".into();
        apply_attr(
            &mut child,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("font-weight".into(), "bolder".into());
                m
            },
            Some(&parent),
        );
        assert_eq!(child.font_weight, "700");
        parent.font_weight = "800".into();
        apply_attr(
            &mut child,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("font-weight".into(), "lighter".into());
                m
            },
            Some(&parent),
        );
        assert_eq!(child.font_weight, "700");
    }

