    #[test]
    fn font_variant_alternates_styleset_and_swash_parse() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert(
                    "font-variant-alternates".into(),
                    "styleset(2) swash ornaments character-variant(3)".into(),
                );
                m
            },
            None,
        );
        assert!(styleset_indices(&st).contains(&2));
        assert!(style_swash(&st));
        assert!(style_ornaments(&st));
        assert!(character_variant_indices(&st).contains(&3));
        // feature-settings ss01 / swsh
        let mut st2 = Style::default();
        st2.font_feature_settings = "\"ss01\" 1, \"swsh\" on".into();
        assert!(styleset_indices(&st2).contains(&1));
        assert!(style_swash(&st2));
        let a = '\u{0251}';
        let g = '\u{0261}';
        assert_eq!(apply_styleset1_forms("bag"), format!("b{a}{g}"));
        assert!(apply_swash_forms("H").contains('\u{210B}'));
        assert_eq!(
            apply_ornament_forms("*+"),
            format!("{}{}", '\u{2767}', '\u{2756}')
        );
        assert_eq!(
            apply_styleset2_forms("12"),
            format!("{}{}", '\u{FF11}', '\u{FF12}')
        );
        let mut st3 = Style::default();
        st3.font_variant_alternates = "styleset(1)".into();
        assert_eq!(
            apply_font_variant_alternates("bag", &st3),
            format!("b{a}{g}")
        );
    }

