    #[test]
    fn font_variant_emoji_presentation_inserts_vs() {
        assert_eq!(apply_emoji_presentation("A", "emoji"), "A");
        let heart = '\u{2764}';
        let emoji = apply_emoji_presentation(&heart.to_string(), "emoji");
        assert!(emoji.contains('\u{FE0F}'), "got {emoji:?}");
        let text = apply_emoji_presentation(&heart.to_string(), "text");
        assert!(text.contains('\u{FE0E}'), "got {text:?}");
        let already = format!("{heart}\u{FE0F}");
        assert_eq!(apply_emoji_presentation(&already, "emoji"), already);
        let mut st = Style::default();
        st.font_variant_emoji = "emoji".into();
        assert_eq!(style_emoji_presentation(&st), Some("emoji"));
        st.font_variant_emoji = "text".into();
        assert_eq!(style_emoji_presentation(&st), Some("text"));
    }

