    #[test]
    fn math_style_compact_and_depth_scale_font_size() {
        let mut st = Style::default();
        st.font_size = 100.0;
        st.math_style = "normal".into();
        st.math_depth = "0".into();
        assert!((math_script_scale(&st) - 1.0).abs() < 1e-9);
        st.math_style = "compact".into();
        assert!((math_script_scale(&st) - 0.71).abs() < 1e-9);
        st.math_depth = "2".into();
        // compact + depth 2 → 0.71^3
        assert!((math_script_scale(&st) - 0.71f64.powi(3)).abs() < 1e-9);
        st.math_style = "normal".into();
        st.math_depth = "auto-add".into();
        assert!((math_script_scale(&st) - 0.71).abs() < 1e-9);
        // Integration: compact text should still outline.
        let svg = br#"<svg xmlns="http://www.w3.org/2000/svg" width="200" height="40">
            <text x="0" y="30" font-size="20" math-style="compact" math-depth="1">x2</text>
        </svg>"#;
        let conv = svg_to_shapes(svg, 2_000_000, 400_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
    }


