    #[test]
    fn path_stroke_alignment_inner_scales_geometry() {
        // Axis-unaligned path (not rect preset): square via path d.
        let outer = br#"<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100">
            <path d="M10 10 H90 V90 H10 Z" fill="none" stroke="black" stroke-width="10"
                  stroke-alignment="outer"/>
        </svg>"#;
        let inner = br#"<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100">
            <path d="M10 10 H90 V90 H10 Z" fill="none" stroke="black" stroke-width="10"
                  stroke-alignment="inner"/>
        </svg>"#;
        let c_out = svg_to_shapes(outer, 1_000_000, 1_000_000, 2).unwrap();
        let c_in = svg_to_shapes(inner, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!c_out.shapes.is_empty() && !c_in.shapes.is_empty());
        // Factor helper unit
        let segs = parse_path("M0 0 H100 V100 H0 Z");
        let d_in = stroke_align_inset_outset(5.0, "inner");
        assert!((d_in - 5.0).abs() < 1e-9);
        let scaled = apply_path_stroke_alignment(
            segs,
            &{
                let mut st = Style::default();
                st.stroke = Some("black".into());
                st.stroke_width = 10.0;
                st.stroke_alignment = "inner".into();
                st
            },
            "path",
        );
        let (x0, y0, x1, y1) = bounds(&scaled).unwrap();
        assert!((x1 - x0) < 100.0 - 1.0, "inner should shrink, got {}", x1 - x0);
    }

