    #[test]
    fn font_optical_sizing_none_identity() {
        let mut st = Style::default();
        st.font_size = 48.0;
        st.font_optical_sizing = "auto".into();
        // auto without opsz axis: identity (fidelity-safe default)
        assert!((optical_sizing_scale(&st) - 1.0).abs() < 1e-12);
        st.font_variation_settings = r#""opsz" 12"#.into();
        let big = optical_sizing_scale(&st);
        assert!(big > 1.0, "48px vs opsz 12 should enlarge mildly, got {big}");
        st.font_optical_sizing = "none".into();
        assert!((optical_sizing_scale(&st) - 1.0).abs() < 1e-12);
        st.font_optical_sizing = "auto".into();
        st.font_size = 6.0;
        st.font_variation_settings = r#""opsz" 12"#.into();
        let small = optical_sizing_scale(&st);
        assert!(small < 1.0 && small > 0.85, "got {small}");
    }

