    fn font_variation_wght_overrides_weight() {
        let mut st = Style::default();
        st.font_weight = "400".into();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert(
                    "font-variation-settings".into(),
                    r#""wght" 700, "wdth" 100"#.into(),
                );
                m
            },
            None,
        );
        assert!(st.font_variation_settings.contains("wght"));
        assert_eq!(effective_font_weight(&st), 700);
        assert_eq!(
            font_variation_axis(&st.font_variation_settings, "wdth").unwrap(),
            100.0
        );
        assert!((effective_font_stretch(&st) - 1.0).abs() < 1e-6);
        st.font_stretch = 1.0;
        st.font_variation_settings = r#""wdth" 75"#.into();
        assert!((effective_font_stretch(&st) - 0.75).abs() < 1e-6);
        // No wght → fall back to font-weight
        st.font_variation_settings = "normal".into();
        assert_eq!(effective_font_weight(&st), 400);
    }


    #[test]
    fn viewport_fill_paints_root_background() {
        let svg = br##"
        <svg viewBox="0 0 100 50" xmlns="http://www.w3.org/2000/svg"
             viewport-fill="#00ff00" viewport-fill-opacity="0.5">
          <rect x="10" y="10" width="20" height="20" fill="#f00"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        // Background + content rect
        assert!(conv.shapes.len() >= 2, "got {}", conv.shapes.len());
        // First shape should cover full viewport roughly
        let mut first_cx = 0i64;
        if let Some(sh) = conv.shapes.first() {
            for d in sh.descendants() {
                if d.local_name == "ext" {
                    if let Some(cx) = d.get_attribute("cx").and_then(|v| v.parse().ok()) {
                        first_cx = cx;
                    }
                }
            }
        }
        assert!(first_cx > 500_000, "viewport fill should span most of slide, cx={first_cx}");
    }

