    #[test]
    fn css_not_general_sibling_combinator() {
        // :not(.mark ~ rect) excludes every rect that follows a .mark sibling.
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <style>
            rect:not(.mark ~ rect) { fill: #ff8800; }
          </style>
          <rect width="10" height="10"/>
          <rect class="mark" y="15" width="10" height="10"/>
          <rect y="30" width="10" height="10"/>
          <rect y="45" width="10" height="10"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 4);
        let hit: Vec<bool> = conv
            .shapes
            .iter()
            .map(|s| {
                String::from_utf8_lossy(&crate::element::write_element(s).unwrap())
                    .to_ascii_uppercase()
                    .contains("FF8800")
            })
            .collect();
        assert_eq!(
            hit,
            vec![true, true, false, false],
            "expected first two orange, following mark excluded: {hit:?}"
        );
    }

