    #[test]
    fn font_variant_numeric_tabular_nums_widens_narrow_digits() {
        // "111" proportional is narrower than tabular; both emit 3 glyph shapes.
        let prop = br##"
        <svg viewBox="0 0 400 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="50" font-size="48" fill="#112233"
                font-family="Liberation Sans, sans-serif">111</text>
        </svg>"##;
        let tab = br##"
        <svg viewBox="0 0 400 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="50" font-size="48" fill="#112233"
                font-family="Liberation Sans, sans-serif"
                font-variant-numeric="tabular-nums">111</text>
        </svg>"##;
        let cp = svg_to_shapes(prop, 2_000_000, 400_000, 2).unwrap();
        let ct = svg_to_shapes(tab, 2_000_000, 400_000, 2).unwrap();
        assert_eq!(cp.shapes.len(), 3, "prop glyphs {}", cp.shapes.len());
        assert_eq!(ct.shapes.len(), 3, "tab glyphs {}", ct.shapes.len());
        // Parse cx of last glyph via off xform; tabular last digit should sit further right.
        fn last_off_x(shapes: &[crate::element::OpenXmlElement]) -> i64 {
            let xml = crate::element::write_element(shapes.last().unwrap()).unwrap();
            let s = String::from_utf8_lossy(&xml);
            // find first a:off then its x
            if let Some(i) = s.find("<a:off") {
                let sub = &s[i..i + 80];
                if let Some(j) = sub.find("x=\"") {
                    let rest = &sub[j + 3..];
                    let end = rest.find('"').unwrap_or(0);
                    return rest[..end].parse().unwrap_or(0);
                }
            }
            0
        }
        let xp = last_off_x(&cp.shapes);
        let xt = last_off_x(&ct.shapes);
        // Tabular cell is at least as wide as proportional for "1".
        assert!(
            xt >= xp,
            "tabular last digit x should be >= proportional: prop={xp} tab={xt}"
        );
    }

