    #[test]
    fn css_lang_and_empty_pseudos() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <style>
            rect:lang(en) { fill: #112233; }
            circle:empty { fill: #445566; }
          </style>
          <rect width="10" height="10" lang="en-US"/>
          <rect width="10" height="10" y="20" lang="fr"/>
          <circle cx="50" cy="50" r="5"/>
          <circle cx="70" cy="50" r="5"><title>x</title></circle>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 4);
        let a = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[0]).unwrap())
            .to_ascii_uppercase();
        let b = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[1]).unwrap())
            .to_ascii_uppercase();
        let c = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[2]).unwrap())
            .to_ascii_uppercase();
        let d = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[3]).unwrap())
            .to_ascii_uppercase();
        assert!(a.contains("112233"), "en-US should match :lang(en): {a}");
        assert!(!b.contains("112233"), "fr should not match: {b}");
        assert!(c.contains("445566"), "empty circle: {c}");
        assert!(!d.contains("445566"), "circle with title not empty: {d}");
    }

