    #[test]
    fn html_image_attr_densify() {
        let mut m = std::collections::HashMap::new();
        m.insert("decoding".into(), "async".into());
        m.insert("loading".into(), "lazy".into());
        m.insert("fetchpriority".into(), "high".into());
        m.insert("crossorigin".into(), "anonymous".into());
        m.insert("referrerpolicy".into(), "no-referrer".into());
        let mut st = Style::default();
        apply_attr(&mut st, &m, None);
        assert!(
            st.image_orientation.contains("decoding:async"),
            "decoding, got {}",
            st.image_orientation
        );
        assert!(
            st.image_orientation.contains("crossorigin:anonymous"),
            "crossorigin, got {}",
            st.image_orientation
        );
        assert!(
            st.image_resolution.contains("loading:lazy"),
            "loading, got {}",
            st.image_resolution
        );
        assert!(
            st.image_resolution.contains("fetchpriority:high"),
            "fetchpriority, got {}",
            st.image_resolution
        );
        assert!(
            st.image_resolution.contains("referrerpolicy:no-referrer"),
            "referrerpolicy, got {}",
            st.image_resolution
        );
    }

