    #[test]
    fn media_query_helpers_unit() {
        assert!(media_query_list_matches("all"));
        assert!(media_query_list_matches("screen"));
        assert!(!media_query_list_matches("print"));
        assert!(media_query_list_matches("(forced-colors: none)"));
        assert!(!media_query_list_matches("(forced-colors: active)"));
        assert!(media_query_list_matches("screen and (prefers-color-scheme: light)"));
        assert!(!media_query_list_matches("screen and (prefers-color-scheme: dark)"));
        assert!(media_query_list_matches(
            "print, screen and (prefers-reduced-motion: no-preference)"
        ));
        assert!(!media_query_list_matches("not screen"));
        assert!(media_query_list_matches("not print"));
    }

