    fn pattern_href_inherits_children() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <pattern id="base" width="10" height="10" patternUnits="userSpaceOnUse">
              <rect width="10" height="10" fill="#00ff00"/>
            </pattern>
            <pattern id="derived" href="#base" width="10" height="10"
                     patternUnits="userSpaceOnUse"/>
          </defs>
          <rect width="40" height="40" fill="url(#derived)"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        let all = conv
            .shapes
            .iter()
            .map(|sh| {
                String::from_utf8_lossy(&crate::element::write_element(sh).unwrap()).to_ascii_uppercase()
            })
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            all.contains("00FF00") || all.contains("SRGBCLR"),
            "pattern href should inherit green child paint, got {all}"
        );
    }

