    #[test]
    fn fe_color_matrix_saturate_zero_grayscales_solid() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <filter id="sat">
              <feColorMatrix type="saturate" values="0"/>
            </filter>
          </defs>
          <rect width="40" height="40" fill="#ff0000" filter="url(#sat)"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 1);
        let s = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[0]).unwrap())
            .to_ascii_uppercase();
        // Saturate 0 → luminance gray of pure red ≈ 0.2126*255 ≈ 54 (0x36)
        assert!(
            !s.contains("FF0000"),
            "saturate=0 should not keep pure red, got {s}"
        );
        // Expect a gray-ish solid (R≈G≈B)
        assert!(
            s.contains("SRGBCLR") || s.contains("SOLIDFILL"),
            "should still paint solid: {s}"
        );
    }

    #[test]
    fn named_color_rebeccapurple_and_hwb() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <rect width="10" height="10" fill="rebeccapurple"/>
          <rect y="20" width="10" height="10" fill="hwb(0 0% 0%)"/>
          <rect y="40" width="10" height="10" fill="oklch(0.628 0.258 29.2)"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 3);
        let a = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[0]).unwrap())
            .to_ascii_uppercase();
        let b = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[1]).unwrap())
            .to_ascii_uppercase();
        let c = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[2]).unwrap())
            .to_ascii_uppercase();
        assert!(a.contains("663399"), "rebeccapurple #663399, got {a}");
        assert!(b.contains("FF0000"), "hwb pure red, got {b}");
        // oklch ≈ red: first channel high in srgbClr val
        assert!(
            c.contains("SRGBCLR") || c.contains("SOLIDFILL"),
            "oklch should produce solid fill, got {c}"
        );
        // Rough: red component of parsed oklch should dominate — val starts with high hex
        assert!(
            c.contains("FF") || c.contains("FE") || c.contains("F"),
            "oklch red should be reddish, got {c}"
        );
    }

