    #[test]
    fn transform_box_view_box_uses_viewport_for_origin() {
        // fill-box: rotate about element center (50,50) of 100×100 rect at 0,0
        // view-box default with origin 50% 50% uses viewport center.
        let svg = br##"
        <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="100" height="100" fill="#112233"
                style="transform: rotate(0deg); transform-origin: 50% 50%; transform-box: fill-box"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 2_000_000, 2_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 1);
        // Smoke: property accepted. Non-zero rotate covered elsewhere.
        let svg2 = br##"
        <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="40" height="40" fill="#445566"
                style="transform: rotate(90deg); transform-origin: 50% 50%; transform-box: fill-box"/>
        </svg>"##;
        let c2 = svg_to_shapes(svg2, 2_000_000, 2_000_000, 2).unwrap();
        assert_eq!(c2.shapes.len(), 1);
        let xml = crate::element::write_element(&c2.shapes[0]).unwrap();
        let s = String::from_utf8_lossy(&xml);
        // 90° about fill-box center (20,20): rect maps to same 40×40 region.
        assert!(s.contains("a:off") || s.contains("xfrm"), "got {s}");
    }

