#[test]
    fn css_values_math_functions_in_lengths() {
        // min / max / clamp / abs / hypot / round / mod / rem / pow / sqrt / sign
        assert!((parse_length("min(10px, 4px, 20px)").unwrap() - 4.0).abs() < 1e-9);
        assert!((parse_length("max(10px, 4px, 20px)").unwrap() - 20.0).abs() < 1e-9);
        assert!((parse_length("clamp(10px, 5px, 20px)").unwrap() - 10.0).abs() < 1e-9);
        assert!((parse_length("clamp(10px, 15px, 20px)").unwrap() - 15.0).abs() < 1e-9);
        assert!((parse_length("clamp(10px, 25px, 20px)").unwrap() - 20.0).abs() < 1e-9);
        // MIN > MAX → MAX wins (CSS Values).
        assert!((parse_length("clamp(30px, 15px, 20px)").unwrap() - 20.0).abs() < 1e-9);
        assert!((parse_length("abs(-12px)").unwrap() - 12.0).abs() < 1e-9);
        assert!((parse_length("sign(-8px)").unwrap() - -1.0).abs() < 1e-9);
        assert!((parse_length("hypot(3px, 4px)").unwrap() - 5.0).abs() < 1e-9);
        assert!((parse_length("sqrt(81px * 1px)").unwrap() - 9.0).abs() < 1e-9);
        assert!((parse_length("pow(2, 3)").unwrap() - 8.0).abs() < 1e-9);
        assert!((parse_length("round(nearest, 14px, 5px)").unwrap() - 15.0).abs() < 1e-9);
        assert!((parse_length("round(down, 14px, 5px)").unwrap() - 10.0).abs() < 1e-9);
        assert!((parse_length("round(up, 11px, 5px)").unwrap() - 15.0).abs() < 1e-9);
        assert!((parse_length("mod(17px, 5px)").unwrap() - 2.0).abs() < 1e-9);
        assert!((parse_length("rem(17px, 5px)").unwrap() - 2.0).abs() < 1e-9);
        // Trig / progress (CSS Values).
        assert!((parse_length("sin(0)").unwrap() - 0.0).abs() < 1e-9);
        assert!((parse_length("cos(0deg)").unwrap() - 1.0).abs() < 1e-9);
        assert!((parse_length("sin(90deg)").unwrap() - 1.0).abs() < 1e-9);
        assert!((parse_length("tan(45deg)").unwrap() - 1.0).abs() < 1e-6);
        assert!((parse_length("asin(0)").unwrap() - 0.0).abs() < 1e-9);
        assert!((parse_length("acos(1)").unwrap() - 0.0).abs() < 1e-9);
        assert!((parse_length("atan(0)").unwrap() - 0.0).abs() < 1e-9);
        assert!((parse_length("atan2(0, 1)").unwrap() - 0.0).abs() < 1e-9);
        assert!((parse_length("progress(50px, 0px, 100px)").unwrap() - 0.5).abs() < 1e-9);
        assert!((parse_length("progress(-10px, 0px, 100px)").unwrap() - 0.0).abs() < 1e-9);
        assert!((parse_length("progress(150px, 0px, 100px)").unwrap() - 1.0).abs() < 1e-9);
        // Nested calc + math + arithmetic.
        assert!(
            (parse_length("calc(min(10px, 3px) + max(1px, 2px) * 2)").unwrap() - 7.0).abs()
                < 1e-9
        );
        // sin inside calc for a length scale.
        assert!(
            (parse_length("calc(10px * cos(0deg) + 5px)").unwrap() - 15.0).abs() < 1e-9
        );
        // Context-aware % inside min/clamp.
        assert!(
            (parse_length_with_context("min(50%, 40px)", 200.0, 16.0).unwrap() - 40.0).abs()
                < 1e-9
        );
        assert!(
            (parse_length_with_context("clamp(1em, 50%, 3em)", 100.0, 20.0).unwrap() - 50.0)
                .abs()
                < 1e-9
        );
        // End-to-end: stroke-width uses clamp math.
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <rect width="40" height="40" fill="none" stroke="#f00"
                stroke-width="clamp(1px, 4px, 8px)"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 1);
        let xml = crate::element::write_element(&conv.shapes[0]).unwrap();
        let s = String::from_utf8_lossy(&xml);
        assert!(s.contains("a:ln"), "stroke should emit ln, got {s}");
    }

    #[test]
    fn css_values_constants_and_viewport_units() {
        assert!((parse_length("calc(pi * 1px)").unwrap() - std::f64::consts::PI).abs() < 1e-9);
        assert!((parse_length("calc(e * 1px)").unwrap() - std::f64::consts::E).abs() < 1e-9);
        assert!((parse_length_with_context("10cqw", 200.0, 16.0).unwrap() - 20.0).abs() < 1e-9);
        assert!((parse_length_with_context("50svh", 100.0, 16.0).unwrap() - 50.0).abs() < 1e-9);
        assert!((parse_length_with_context("25dvw", 80.0, 16.0).unwrap() - 20.0).abs() < 1e-9);
        assert!((parse_length_with_context("10vi", 50.0, 16.0).unwrap() - 5.0).abs() < 1e-9);
        let inf = eval_simple_calc("infinity").unwrap();
        assert!(inf.is_infinite() && inf.is_sign_positive());
        let ninf = eval_simple_calc("-infinity").unwrap();
        assert!(ninf.is_infinite() && ninf.is_sign_negative());
        assert!(eval_simple_calc("NaN").unwrap().is_nan());
        // min with infinity keeps finite branch
        assert!((parse_length("calc(min(1px, infinity))").unwrap() - 1.0).abs() < 1e-9);
    }

