    #[test]
    fn supports_condition_selector_and_not() {
        assert!(supports_condition_matches("(color: red)"));
        assert!(supports_condition_matches("selector(:hover)"));
        assert!(supports_condition_matches("(display: flex) and selector(div > p)"));
        assert!(!supports_condition_matches("not (color: red)"));
        assert!(supports_condition_matches("(color: red) or (unknown: x)"));
        let svg = br##"
        <svg viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
          <style>
            rect { fill: #111111; }
            @supports selector(:nth-child(odd of .x)) {
              rect { fill: #00aa00; }
            }
            @supports not (color: red) {
              rect { fill: #ff0000; }
            }
          </style>
          <rect width="10" height="10"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        let s = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[0]).unwrap())
            .to_ascii_uppercase();
        assert!(s.contains("00AA00"), "@supports selector should include green, got {s}");
        assert!(!s.contains("FF0000") || s.contains("00AA00"), "not (color:red) must not win over green");
    }

    #[test]
