    #[test]
    fn css_nth_child_of_is_list() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <style>
            * { fill: #111111; }
            :nth-child(1 of :is(.a, .b)) { fill: #00aa00; }
          </style>
          <rect class="a" width="10" height="10" />
          <rect class="x" width="10" height="10" y="12" />
          <rect class="b" width="10" height="10" y="24" />
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        let fills: Vec<String> = conv
            .shapes
            .iter()
            .map(|el| {
                String::from_utf8_lossy(&crate::element::write_element(el).unwrap())
                    .to_ascii_uppercase()
            })
            .collect();
        assert!(fills[0].contains("00AA00"), "first of .a|.b green, got {}", fills[0]);
        assert!(fills[1].contains("111111"), "non-matching dark, got {}", fills[1]);
        assert!(fills[2].contains("111111"), "second of list not 1st, got {}", fills[2]);
    }

