    #[test]
    fn css_nesting_expands_descendant_and_ampersand() {
        let expanded = expand_css_nesting(
            r#".card { fill: #111111; .title { fill: #ff6600; } &.hot { fill: #00aa00; } }"#,
        );
        assert!(
            expanded.contains(".card.hot"),
            "expand should produce .card.hot, got {expanded}"
        );
        assert!(
            expanded.contains("#00aa00") || expanded.contains("#00AA00"),
            "expand should keep green, got {expanded}"
        );
        assert!(
            expanded.contains("#111111"),
            "expand should keep parent fill, got {expanded}"
        );
        // Flat parse should yield usable rules.
        let mut rules = CssRules::default();
        parse_css_block(
            r#".card { fill: #111111; .title { fill: #ff6600; } &.hot { fill: #00aa00; } }"#,
            &mut rules,
        );
        let sels: Vec<String> = rules.rules.iter().map(|r| r.selector.clone()).collect();
        assert!(
            sels.iter().any(|s| s.contains(".card.hot") || s == ".card.hot"),
            "parsed selectors {sels:?} from expanded {expanded}"
        );
        assert!(
            rules.rules.iter().any(|r| {
                r.declarations
                    .get("fill")
                    .map(|v| v.to_ascii_lowercase().contains("00aa00"))
                    .unwrap_or(false)
            }),
            "green fill missing in rules {rules:?} expanded={expanded}"
        );
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <style>
            .card { fill: #111111; &.hot { fill: #00aa00; } }
          </style>
          <rect class="card" width="20" height="20" />
          <rect class="card hot" x="30" width="20" height="20" />
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        let all = conv
            .shapes
            .iter()
            .map(|el| {
                String::from_utf8_lossy(&crate::element::write_element(el).unwrap()).into_owned()
            })
            .collect::<String>()
            .to_ascii_uppercase();
        assert!(
            all.contains("111111"),
            "parent .card fill from nesting, got {all}"
        );
        assert!(
            all.contains("00AA00"),
            "&.hot nested selector should paint green, got {all}"
        );
    }

