    #[test]
    fn css_if_supports_and_media_real_eval() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <style>
            #a { fill: if(supports((color: red)): #00aa00; else: #ff0000); }
            #b { fill: if(supports((not (color: red))): #00aa00; else: #112233); }
            #c { fill: if(media(screen): #00aa00; else: #ff0000); }
            #d { fill: if(media(print): #ff0000; else: #00aa00); }
          </style>
          <rect id="a" width="10" height="10" />
          <rect id="b" x="15" width="10" height="10" />
          <rect id="c" x="30" width="10" height="10" />
          <rect id="d" x="45" width="10" height="10" />
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 4);
        for (i, want) in [(0, "00AA00"), (1, "112233"), (2, "00AA00"), (3, "00AA00")] {
            let s = String::from_utf8_lossy(&crate::element::write_element(&conv.shapes[i]).unwrap())
                .to_ascii_uppercase();
            assert!(s.contains(want), "shape {i} want {want}, got {s}");
        }
        // Direct unit checks for if-condition helpers.
        assert!(supports_condition_matches("(color: red)"));
        assert!(!supports_condition_matches("not (color: red)"));
        assert!(media_query_list_matches("screen"));
        assert!(!media_query_list_matches("print"));
    }

    #[test]
    fn css_sibling_index_and_count_real() {
        // sibling-index() is 1-based; sibling-count() is total element siblings.
        // Map index into fill via discrete rules so cascade must resolve real values.
        let svg = br##"
        <svg viewBox="0 0 120 40" xmlns="http://www.w3.org/2000/svg">
          <style>
            rect { --ok: 1; fill: #111111; }
            rect { fill: if(style(--ok: 1): #00aa00; else: #ff0000); }
            /* opacity encodes index/count so first is 1/3, last is 1 */
            rect { opacity: calc(sibling-index() / sibling-count()); }
          </style>
          <g>
            <rect width="10" height="10" />
            <rect x="15" width="10" height="10" />
            <rect x="30" width="10" height="10" />
          </g>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 400_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 3);
        let xmls: Vec<String> = conv
            .shapes
            .iter()
            .map(|s| {
                String::from_utf8_lossy(&crate::element::write_element(s).unwrap()).into_owned()
            })
            .collect();
        for (i, x) in xmls.iter().enumerate() {
            assert!(
                x.to_ascii_uppercase().contains("00AA00"),
                "sibling cascade broke fill on {i}: {x}"
            );
        }
        // DrawingML solid alpha is transparency: opacity 1/3 => ~66667, opacity 1 => absent/0.
        fn first_alpha(xml: &str) -> Option<i64> {
            let lower = xml.to_ascii_lowercase();
            let key = "val=";
            let mut search = 0usize;
            while let Some(rel) = lower[search..].find("a:alpha") {
                let at = search + rel;
                if let Some(vrel) = lower[at..].find(key) {
                    let start = at + vrel + key.len();
                    // skip optional quote
                    let bytes = lower.as_bytes();
                    let mut i = start;
                    if i < bytes.len() && (bytes[i] == b'"' || bytes[i] == b'\'') {
                        i += 1;
                    }
                    let begin = i;
                    while i < bytes.len() && bytes[i].is_ascii_digit() {
                        i += 1;
                    }
                    if i > begin {
                        if let Ok(n) = lower[begin..i].parse::<i64>() {
                            return Some(n);
                        }
                    }
                }
                search = at + 7;
            }
            None
        }
        let a0 = first_alpha(&xmls[0]);
        let a2 = first_alpha(&xmls[2]);
        match (a0, a2) {
            (Some(t0), None) => assert!(t0 > 30_000, "first sibling translucent, alpha={t0}"),
            (Some(t0), Some(t2)) => assert!(t0 > t2 + 10_000, "index order {t0} vs {t2}"),
            (None, None) => panic!("expected alpha differentiation from sibling-index"),
            other => panic!("unexpected alpha pair {other:?}"),
        }
    }

