    #[test]
    fn text_wrap_balance_evens_line_widths() {
        let fonts = font::FontDb::global();
        let mut st = Style::default();
        st.font_size = 20.0;
        st.font_family = "DejaVu Sans".into();
        st.text_wrap = "balance".into();
        // Wide enough for 2+ lines of latin words; balance should reduce max width
        // variance vs greedy-only wrap.
        let text = "alpha bravo charlie delta echo foxtrot golf hotel";
        let max_w = 180.0;
        let greedy = {
            let mut s = st.clone();
            s.text_wrap = "wrap".into();
            wrap_text_lines(text, max_w, &s, fonts)
        };
        let balanced = wrap_text_lines(text, max_w, &st, fonts);
        assert!(
            balanced.len() >= 2,
            "expected multi-line wrap, got {balanced:?}"
        );
        let max_g = greedy
            .iter()
            .map(|l| measure_text_run_width(l, &st, fonts))
            .fold(0.0_f64, f64::max);
        let max_b = balanced
            .iter()
            .map(|l| measure_text_run_width(l, &st, fonts))
            .fold(0.0_f64, f64::max);
        // Balanced packing should not exceed greedy max line width.
        assert!(
            max_b <= max_g + 1.0,
            "balance max {max_b} should be <= greedy max {max_g}; lines={balanced:?} greedy={greedy:?}"
        );
        // And should not produce more lines than greedy (within +1 for edge cases).
        assert!(
            balanced.len() <= greedy.len() + 1,
            "balance line count {} vs greedy {}",
            balanced.len(),
            greedy.len()
        );
    }

    #[test]
    fn text_wrap_pretty_and_balance_cascade() {
        let mut m = std::collections::HashMap::new();
        m.insert("text-wrap".into(), "pretty".into());
        let mut st = Style::default();
        apply_attr(&mut st, &m, None);
        assert_eq!(st.text_wrap, "pretty");
        m.insert("text-wrap".into(), "balance".into());
        apply_attr(&mut st, &m, None);
        assert_eq!(st.text_wrap, "balance");
    }

