#[test]
    fn css_defined_scope_dir_any_link() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" dir="rtl">
          <style>
            :defined { fill: #112233; }
            :dir(rtl) .b { fill: #00aa00; }
            a:any-link rect { fill: #0000ff; }
          </style>
          <rect class="a" width="10" height="10"/>
          <rect class="b" y="20" width="10" height="10"/>
          <a href="#x"><rect class="c" y="40" width="10" height="10"/></a>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(conv.shapes.len() >= 3);
        let shapes: Vec<String> = conv
            .shapes
            .iter()
            .map(|s| {
                String::from_utf8_lossy(&crate::element::write_element(s).unwrap())
                    .to_ascii_uppercase()
            })
            .collect();
        // :defined applies to all → first rect may be 112233 (or overridden)
        assert!(
            shapes.iter().any(|s| s.contains("112233") || s.contains("00AA00") || s.contains("0000FF")),
            "pseudos should paint, got {shapes:?}"
        );
        // .b under rtl should be green
        assert!(
            shapes.iter().any(|s| s.contains("00AA00")),
            ":dir(rtl) .b green, got {shapes:?}"
        );
        // rect under a:any-link → blue (or still defined color if specificity loses)
        assert!(
            shapes.iter().any(|s| s.contains("0000FF")),
            "a:any-link rect blue, got {shapes:?}"
        );
    }

    #[test]
    fn css_has_descendant_selector() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <style>
            g:has(> .mark) { fill: #ff00aa; }
            g:has(.deep) rect { fill: #00ffaa; }
          </style>
          <g>
            <rect class="mark" width="10" height="10"/>
          </g>
          <g>
            <g><rect class="deep" y="20" width="10" height="10"/></g>
          </g>
          <g>
            <rect y="40" width="10" height="10" fill="#112233"/>
          </g>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(conv.shapes.len() >= 3);
        let shapes: Vec<String> = conv
            .shapes
            .iter()
            .map(|s| {
                String::from_utf8_lossy(&crate::element::write_element(s).unwrap())
                    .to_ascii_uppercase()
            })
            .collect();
        assert!(
            shapes.iter().any(|s| s.contains("FF00AA")),
            "g:has(> .mark) pink, got {shapes:?}"
        );
        assert!(
            shapes.iter().any(|s| s.contains("00FFAA")),
            "g:has(.deep) rect teal, got {shapes:?}"
        );
        // third group rect keeps explicit fill
        assert!(
            shapes.iter().any(|s| s.contains("112233")),
            "unmatched group keeps fill, got {shapes:?}"
        );
    }

    #[test]
    fn css_has_sibling_relative_selector() {
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <style>
            .a:has(+ .b) { fill: #aa00ff; }
            .c:has(~ .d) { fill: #00aaff; }
          </style>
          <rect class="a" width="10" height="10"/>
          <rect class="b" x="20" width="10" height="10" fill="#111111"/>
          <rect class="c" y="20" width="10" height="10"/>
          <rect class="x" y="20" x="20" width="10" height="10" fill="#222222"/>
          <rect class="d" y="20" x="40" width="10" height="10" fill="#333333"/>
          <rect class="a" y="40" width="10" height="10" fill="#444444"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        let shapes: Vec<String> = conv
            .shapes
            .iter()
            .map(|s| {
                String::from_utf8_lossy(&crate::element::write_element(s).unwrap())
                    .to_ascii_uppercase()
            })
            .collect();
        assert!(
            shapes.iter().any(|s| s.contains("AA00FF")),
            ".a:has(+ .b) purple, got {shapes:?}"
        );
        assert!(
            shapes.iter().any(|s| s.contains("00AAFF")),
            ".c:has(~ .d) cyan, got {shapes:?}"
        );
        // trailing .a without following .b keeps explicit fill
        assert!(
            shapes.iter().any(|s| s.contains("444444")),
            "lone .a keeps fill, got {shapes:?}"
        );
    }

