    #[test]
    fn stroke_width_percent_uses_viewport_diagonal() {
        // viewBox 100x100 → normalized diagonal = sqrt((100^2+100^2)/2) = 100
        // stroke-width 2% → 2 user units
        let svg = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <line x1="0" y1="50" x2="100" y2="50" stroke="#ff0000" stroke-width="2%"/>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), 1);
        let xml = crate::element::write_element(&conv.shapes[0]).unwrap();
        let s = String::from_utf8_lossy(&xml);
        // EMU: 2 user * (1e6/100) = 20000; thin stroke ×0.84 → ~16800
        assert!(
            s.contains(r#"w="16800""#)
                || s.contains(r#"w="20000""#)
                || s.contains(r#"w="16799""#)
                || s.contains(r#"w="16801""#),
            "2% of diag 100 → ~2px stroke EMU, got {s}"
        );
    }

