    #[test]
    fn text_align_maps_to_text_anchor() {
        let svg = br##"
        <svg viewBox="0 0 200 50" xmlns="http://www.w3.org/2000/svg">
          <text x="100" y="30" font-size="20" text-align="center" fill="#112233">A</text>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv.shapes.is_empty());
        // Centered at x=100 → glyph origin shifted left of 100; shape x should be < 100 in user?
        // Just ensure it emits (anchor path exercised).
        let svg2 = br##"
        <svg viewBox="0 0 200 50" xmlns="http://www.w3.org/2000/svg">
          <text x="100" y="30" font-size="20" text-anchor="middle" fill="#112233">A</text>
        </svg>"##;
        let conv2 = svg_to_shapes(svg2, 1_000_000, 1_000_000, 2).unwrap();
        assert_eq!(conv.shapes.len(), conv2.shapes.len());
        // Positions should be close (same anchor semantics)
        let x1 = crate::element::write_element(&conv.shapes[0]).unwrap();
        let x2 = crate::element::write_element(&conv2.shapes[0]).unwrap();
        let s1 = String::from_utf8_lossy(&x1);
        let s2 = String::from_utf8_lossy(&x2);
        // Extract a:off x=
        fn off_x(s: &str) -> Option<i64> {
            let key = "x=\"";
            let i = s.find(key)?;
            let rest = &s[i + key.len()..];
            let end = rest.find('"')?;
            rest[..end].parse().ok()
        }
        let a = off_x(&s1);
        let b = off_x(&s2);
        assert_eq!(a, b, "text-align:center should match text-anchor:middle ({a:?} vs {b:?})");
    }

    
    #[test]
    fn text_align_justify_stores_and_inherits() {
        let mut st = Style::default();
        apply_attr(
            &mut st,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("text-align".into(), "justify".into());
                m.insert("text-justify".into(), "inter-character".into());
                m
            },
            None,
        );
        assert_eq!(st.text_align, "justify");
        assert_eq!(st.text_anchor, "start");
        assert_eq!(st.text_justify, "inter-character");
        let mut child = st.clone();
        apply_attr(
            &mut child,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("text-align".into(), "inherit".into());
                m
            },
            Some(&st),
        );
        assert_eq!(child.text_align, "justify");
        apply_attr(
            &mut child,
            &{
                let mut m = std::collections::HashMap::new();
                m.insert("text-align".into(), "justify-all".into());
                m
            },
            Some(&st),
        );
        assert_eq!(child.text_align, "justify-all");
    }

    #[test]
    fn justify_extra_spacing_inter_word_and_character() {
        let fonts = font::FontDb::global();
        let mut st = Style::default();
        st.font_size = 20.0;
        st.font_family = "serif".into();
        st.text_justify = "inter-word".into();
        let line = "aa bb";
        let natural = measure_text_run_width(line, &st, &fonts);
        let max_w = natural + 20.0;
        let (ls, ws) = justify_extra_spacing(line, max_w, &st, &fonts);
        assert!(ls.abs() < 1e-6, "inter-word should not use letter gaps when spaces exist: ls={ls}");
        assert!((ws - 20.0).abs() < 0.5, "one space absorbs full slack: ws={ws}");
        st.text_justify = "inter-character".into();
        let (ls2, ws2) = justify_extra_spacing(line, max_w, &st, &fonts);
        assert!(ws2.abs() < 1e-6, "inter-character ignores word gaps: ws={ws2}");
        assert!(ls2 > 0.0, "letter spacing expands: ls={ls2}");
        // Re-measure with extras should approach max_w.
        st.letter_spacing += ls2;
        st.word_spacing += ws2;
        let filled = measure_text_run_width(line, &st, &fonts);
        assert!((filled - max_w).abs() < 1.0, "filled={filled} max={max_w}");
    }

    #[test]
    fn text_align_justify_emits_wider_than_natural() {
        // Narrow textLength forces wrap; justify should expand first line toward full width.
        let svg = br##"
        <svg viewBox="0 0 200 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="30" font-size="16" textLength="120" lengthAdjust="spacing"
                text-align="justify" text-justify="inter-character"
                fill="#112233">ABCDEFGHIJKLMNOP</text>
        </svg>"##;
        let conv = svg_to_shapes(svg, 1_000_000, 1_000_000, 2).unwrap();
        assert!(
            conv.shapes.len() >= 2,
            "expected multi-line glyph shapes, got {}",
            conv.shapes.len()
        );
        // Control without justify should also emit; ensure justify path doesn't panic/empty.
        let svg2 = br##"
        <svg viewBox="0 0 200 80" xmlns="http://www.w3.org/2000/svg">
          <text x="10" y="30" font-size="16" textLength="120" lengthAdjust="spacing"
                text-align="start" fill="#112233">ABCDEFGHIJKLMNOP</text>
        </svg>"##;
        let conv2 = svg_to_shapes(svg2, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!conv2.shapes.is_empty());
        // Justified run should produce at least as many shapes (same glyphs) and
        // typically a wider x-extent on the first soft line.
        assert!(
            conv.shapes.len() >= conv2.shapes.len().saturating_sub(2),
            "justify={} start={}",
            conv.shapes.len(),
            conv2.shapes.len()
        );
    }

