    #[test]
    fn shape_rendering_crisp_skips_thin_stroke_nudge() {
        // Default path applies ×0.84 on ≤2.5px strokes; crispEdges keeps full width.
        let soft = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <line x1="0" y1="50" x2="100" y2="50" stroke="#000" stroke-width="2"/>
        </svg>"##;
        let crisp = br##"
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
          <line x1="0" y1="50" x2="100" y2="50" stroke="#000" stroke-width="2"
                shape-rendering="crispEdges"/>
        </svg>"##;
        let a = svg_to_shapes(soft, 1_000_000, 1_000_000, 2).unwrap();
        let b = svg_to_shapes(crisp, 1_000_000, 1_000_000, 2).unwrap();
        assert!(!a.shapes.is_empty() && !b.shapes.is_empty());
        let xa = crate::element::write_element(&a.shapes[0]).unwrap();
        let xb = crate::element::write_element(&b.shapes[0]).unwrap();
        let sa = String::from_utf8_lossy(&xa);
        let sb = String::from_utf8_lossy(&xb);
        // Prefer stroke line width attribute over path PATH_SPACE `w=`.
        fn ln_w(s: &str) -> Option<i64> {
            let i = s.find("<a:ln ")?;
            let rest = &s[i..];
            let j = rest.find("w=\"")?;
            let r2 = &rest[j + 3..];
            let end = r2.find('"')?;
            r2[..end].parse().ok()
        }
        let wa = ln_w(&sa).expect("soft stroke w");
        let wb = ln_w(&sb).expect("crisp stroke w");
        assert!(wb > wa, "crisp should be wider than nudged soft: {wb} vs {wa}");
        // EMU: 2 user * (1e6/100) = 20000; soft ≈ 16800
        assert!((wb - 20_000).abs() < 50, "crisp w≈20000 got {wb}");
        assert!((wa as f64 - 20_000.0 * 0.84).abs() < 50.0, "soft w≈16800 got {wa}");
    }

