    #[test]
    fn parse_css_filter_functions_unit() {
        let (b, sh, ex, p) = parse_css_filter_functions("blur(3px)").unwrap();
        assert!((b - 3.0).abs() < 1e-6);
        assert!(sh.is_none());
        assert!(ex.is_empty());
        assert!(p.is_identity());
        let (b2, sh2, ex2, _) = parse_css_filter_functions("drop-shadow(2px 3px 1px #112233)").unwrap();
        let sh2 = sh2.expect("shadow");
        assert!((sh2.dx - 2.0).abs() < 1e-6 && (sh2.dy - 3.0).abs() < 1e-6);
        assert!((sh2.blur - 1.0).abs() < 1e-6);
        assert_eq!(sh2.rgb, [0x11, 0x22, 0x33]);
        assert!(ex2.is_empty());
        assert!(b2 >= 1.0);
        let (_, _, _, p3) = parse_css_filter_functions("opacity(50%) grayscale(1)").unwrap();
        assert!((p3.opacity_scale - 0.5).abs() < 1e-6);
        assert!(p3.color_matrix.is_some());
        let (_, sh3, ex3, _) = parse_css_filter_functions(
            "drop-shadow(1px 1px 0 #000) drop-shadow(2px 3px 1px #fff)",
        )
        .unwrap();
        assert!(sh3.is_some());
        assert_eq!(ex3.len(), 1);
        assert!((ex3[0].dx - 2.0).abs() < 1e-6);
    }

    #[test]
